-- S2-1.1 根据系统需求绘制 E-R 图。 (node_id=271)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (271, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (271, 1, '[{"id": "s2-1-1-b1", "t": "table", "imp": "core", "title": "E-R 图（实体-联系图）三大核心要素与图形符号", "headers": ["组成要素", "E-R 图几何图形", "概念说明", "典型实例"], "rows": [["==实体（Entity）==", "==矩形框==", "客观存在并可相互区分的事物集合（框内写实体名）", "学生、课程、教师、部门"], ["==属性（Attribute）==", "==椭圆形框==", "实体或联系所具有的特征（用无向边与实体/联系相连）", "学号（主码下加横线）、姓名、成绩"], ["==联系（Relationship）==", "==菱形框==", "实体集之间的对应关系，用无向边连接实体并在边上标注联系类型", "选修（`m : n`）、属于（`n : 1`）、管理（`1 : 1`）"]]}, {"id": "s2-1-1-b2", "t": "table", "imp": "core", "title": "三类实体联系（1:1、1:n、m:n）向关系模式（表）转换铁律", "headers": ["联系基数", "转换后的表数量与外键归属规则", "专转本高频大题应用示例"], "rows": [["一对一 `1 : 1`", "可合并为 1 张表，或各自建表并==在任意一方加入对方的主键作为外键==", "班级 `(班号, 班名)` 与班长 `(学号, 姓名)`"], ["一对多 ==`1 : n`==", "==在 `n` 端（多方）实体的表中，加入 `1` 端（一方）实体的主键作为外键==（不单独建联系表）", "部门(1)—员工(n)：在**员工表**中增加 `dept_id` 外键"], ["多对多 ==`m : n`==", "==必须单独为“联系”建立一张新表==，新表包含**两端实体的主键（联合构成主码或外键）**及联系自身的属性", "学生(m)—选课—课程(n)：新建**选课表 `(学号, 课程号, 成绩)`**"]]}, {"id": "s2-1-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "E-R 图转关系模式高频丢分点", "text": "多对多 `m : n` 联系自身的属性（例如“选课”联系上的**成绩**、借阅联系上的**借阅日期**）==必须存放在独立转换出的联系表中==，绝不能放进学生表或课程表！"}]'::jsonb, '', 'S2-1.1 根据系统需求绘制 E-R 图。 E-R 图（实体-联系图）三大核心要素与图形符号 组成要素 E-R 图几何图形 概念说明 典型实例 实体（Entity） 矩形框 客观存在并可相互区分的事物集合（框内写实体名） 学生、课程、教师、部门 属性（Attribute） 椭圆形框 实体或联系所具有的特征（用无向边与实体/联系相连） 学号（主码下加横线）、姓名、成绩 联系（Relationship） 菱形框 实体集之间的对应关系，用无向边连接实体并在边上标注联系类型 选修（m : n）、属于（n : 1）、管理（1 : 1） 三类实体联系（1:1、1:n、m:n）向关系模式（表）转换铁律 联系基数 转换后的表数量与外键归属规则 专转本高频大题应用示例 一对一 1 : 1 可合并为 1 张表，或各自建表并在任意一方加入对方的主键作为外键 班级 (班号, 班名) 与班长 (学号, 姓名) 一对多 1 : n 在 n 端（多方）实体的表中，加入 1 端（一方）实体的主键作为外键（不单独建联系表） 部门(1)—员工(n)：在员工表中增加 dept_id 外键 多对多 m : n 必须单独为“联系”建立一张新表，新表包含两端实体的主键（联合构成主码或外键）及联系自身的属性 学生(m)—选课—课程(n)：新建选课表 (学号, 课程号, 成绩) E-R 图转关系模式高频丢分点 多对多 m : n 联系自身的属性（例如“选课”联系上的成绩、借阅联系上的借阅日期）必须存放在独立转换出的联系表中，绝不能放进学生表或课程表！', '{"pdf": "操作技能复习.pdf", "pages": [61, 62, 63, 64]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-2.1 创建配置数据库。 (node_id=273)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (273, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (273, 1, '[{"id": "s2-2-1-b1", "t": "list", "imp": "core", "title": "MySQL 数据库创建、查看、切换与字符集配置命令", "ordered": false, "items": ["创建数据库：==`CREATE DATABASE [IF NOT EXISTS] 数据库名 [DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci];`==（加 `IF NOT EXISTS` 可避免同名库已存在时报错）。", "查看与选择数据库：`SHOW DATABASES;` 查看所有库；`SHOW CREATE DATABASE 库名;` 查看创建定义；==`USE 数据库名;`== 切换当前工作数据库。", "修改数据库字符集：==`ALTER DATABASE 数据库名 DEFAULT CHARACTER SET 字符集名 [COLLATE 校对规则];`==。"]}, {"id": "s2-2-1-b2", "t": "code", "imp": "important", "title": "创建并切换数据库标准 SQL 示例", "lang": "sql", "code": "CREATE DATABASE IF NOT EXISTS school_db\n  DEFAULT CHARACTER SET utf8mb4\n  COLLATE utf8mb4_general_ci;\n\nUSE school_db;"}]'::jsonb, '', 'S2-2.1 创建配置数据库。 MySQL 数据库创建、查看、切换与字符集配置命令 创建数据库：CREATE DATABASE [IF NOT EXISTS] 数据库名 [DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci];（加 IF NOT EXISTS 可避免同名库已存在时报错）。 查看与选择数据库：SHOW DATABASES; 查看所有库；SHOW CREATE DATABASE 库名; 查看创建定义；USE 数据库名; 切换当前工作数据库。 修改数据库字符集：ALTER DATABASE 数据库名 DEFAULT CHARACTER SET 字符集名 [COLLATE 校对规则];。 创建并切换数据库标准 SQL 示例 CREATE DATABASE IF NOT EXISTS school_db
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_general_ci;

USE school_db;', '{"pdf": "操作技能复习.pdf", "pages": [65, 66, 67]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-2.2 使用合适的数据类型创建表。 (node_id=274)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (274, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (274, 1, '[{"id": "s2-2-2-b1", "t": "table", "imp": "core", "title": "MySQL 常用数据类型与六大完整性约束", "headers": ["类别", "常用类型 / 约束关键字", "字节数 / 语法说明", "高频选型与考试要点"], "rows": [["整型", "`TINYINT(1B)`、`SMALLINT(2B)`、`INT(4B)`、`BIGINT(8B)`", "可配 `UNSIGNED` 无符号", "年龄/状态用 `TINYINT`，自增主键用 `INT AUTO_INCREMENT`"], ["定点与浮点", "`DECIMAL(M, D)` vs `FLOAT(4B)` / `DOUBLE(8B)`", "`M` 为总位数，`D` 为小数位", "==金额、价格、成绩等精确小数首选 `DECIMAL(10,2)`=="], ["字符串", "==`CHAR(n)` 定长== vs ==`VARCHAR(n)` 变长==、`TEXT`", "`CHAR` 固定占 `n` 字符；`VARCHAR` 按实际长度存", "身份证号(18位)/性别用 `CHAR`；姓名/地址用 `VARCHAR`"], ["日期时间", "`DATE`、`TIME`、`DATETIME`、`TIMESTAMP`", "`YYYY-MM-DD` / `YYYY-MM-DD HH:MM:SS`", "出生日期用 `DATE`，下单时间用 `DATETIME`"], ["六大约束", "==`PRIMARY KEY`==、`FOREIGN KEY`、`NOT NULL`、`UNIQUE`、`DEFAULT`、`AUTO_INCREMENT`", "主键非空且唯一（每表最多 1 个主键）", "`UNIQUE` 唯一约束允许多个 `NULL`，而 `PRIMARY KEY` 绝不允许 `NULL`"]]}, {"id": "s2-2-2-b2", "t": "code", "imp": "core", "title": "含主键、自增、默认、非空与外键的建表模板", "lang": "sql", "code": "CREATE TABLE student (\n    sno CHAR(10) PRIMARY KEY,\n    sname VARCHAR(20) NOT NULL,\n    gender CHAR(1) DEFAULT ''男'',\n    age TINYINT UNSIGNED,\n    dept_id INT,\n    CONSTRAINT fk_stu_dept FOREIGN KEY (dept_id) REFERENCES dept(id)\n);"}]'::jsonb, '', 'S2-2.2 使用合适的数据类型创建表。 MySQL 常用数据类型与六大完整性约束 类别 常用类型 / 约束关键字 字节数 / 语法说明 高频选型与考试要点 整型 TINYINT(1B)、SMALLINT(2B)、INT(4B)、BIGINT(8B) 可配 UNSIGNED 无符号 年龄/状态用 TINYINT，自增主键用 INT AUTO_INCREMENT 定点与浮点 DECIMAL(M, D) vs FLOAT(4B) / DOUBLE(8B) M 为总位数，D 为小数位 金额、价格、成绩等精确小数首选 DECIMAL(10,2) 字符串 CHAR(n) 定长 vs VARCHAR(n) 变长、TEXT CHAR 固定占 n 字符；VARCHAR 按实际长度存 身份证号(18位)/性别用 CHAR；姓名/地址用 VARCHAR 日期时间 DATE、TIME、DATETIME、TIMESTAMP YYYY-MM-DD / YYYY-MM-DD HH:MM:SS 出生日期用 DATE，下单时间用 DATETIME 六大约束 PRIMARY KEY、FOREIGN KEY、NOT NULL、UNIQUE、DEFAULT、AUTO_INCREMENT 主键非空且唯一（每表最多 1 个主键） UNIQUE 唯一约束允许多个 NULL，而 PRIMARY KEY 绝不允许 NULL 含主键、自增、默认、非空与外键的建表模板 CREATE TABLE student (
    sno CHAR(10) PRIMARY KEY,
    sname VARCHAR(20) NOT NULL,
    gender CHAR(1) DEFAULT ''男'',
    age TINYINT UNSIGNED,
    dept_id INT,
    CONSTRAINT fk_stu_dept FOREIGN KEY (dept_id) REFERENCES dept(id)
);', '{"pdf": "操作技能复习.pdf", "pages": [68]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-2.3 修改表结构。 (node_id=275)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (275, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (275, 1, '[{"id": "s2-2-3-b1", "t": "table", "imp": "core", "title": "ALTER TABLE 修改表结构高频子句速查表（必背）", "headers": ["操作目的", "标准 SQL 语法（`ALTER TABLE 表名 ...`）", "关键区分点"], "rows": [["重命名表", "==`ALTER TABLE 旧表名 RENAME [TO] 新表名;`==", "也可写 `RENAME TABLE 旧表名 TO 新表名;`"], ["新增字段", "==`ALTER TABLE 表名 ADD [COLUMN] 字段名 数据类型 [约束] [FIRST | AFTER 某列];`==", "`FIRST` 插在首列，`AFTER col` 插在指定列后"], ["修改类型/位置", "==`ALTER TABLE 表名 MODIFY [COLUMN] 字段名 新数据类型 [约束];`==", "`MODIFY` **只改数据类型或约束，不改字段名**"], ["修改字段名+类型", "==`ALTER TABLE 表名 CHANGE [COLUMN] 旧字段名 新字段名 新数据类型;`==", "`CHANGE` **可同时改列名和类型**（即使不改类型也必须重写类型）"], ["删除字段", "==`ALTER TABLE 表名 DROP [COLUMN] 字段名;`==", "直接移除该列及其全部数据"]]}]'::jsonb, '', 'S2-2.3 修改表结构。 ALTER TABLE 修改表结构高频子句速查表（必背） 操作目的 标准 SQL 语法（ALTER TABLE 表名 ...） 关键区分点 重命名表 ALTER TABLE 旧表名 RENAME [TO] 新表名; 也可写 RENAME TABLE 旧表名 TO 新表名; 新增字段 ALTER TABLE 表名 ADD [COLUMN] 字段名 数据类型 [约束] [FIRST | AFTER 某列]; FIRST 插在首列，AFTER col 插在指定列后 修改类型/位置 ALTER TABLE 表名 MODIFY [COLUMN] 字段名 新数据类型 [约束]; MODIFY 只改数据类型或约束，不改字段名 修改字段名+类型 ALTER TABLE 表名 CHANGE [COLUMN] 旧字段名 新字段名 新数据类型; CHANGE 可同时改列名和类型（即使不改类型也必须重写类型） 删除字段 ALTER TABLE 表名 DROP [COLUMN] 字段名; 直接移除该列及其全部数据', '{"pdf": "操作技能复习.pdf", "pages": [69]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-2.4 删除表和数据库。 (node_id=276)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (276, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (276, 1, '[{"id": "s2-2-4-b1", "t": "list", "imp": "core", "title": "DROP 删除库表与 TRUNCATE / DELETE 区别", "ordered": false, "items": ["删除数据库：==`DROP DATABASE [IF EXISTS] 数据库名;`==（永久删除库及其中所有表）。", "删除数据表：==`DROP TABLE [IF EXISTS] 表名;`==；若表被其他表的外键引用（父表），**必须先删除子表或先解除外键约束**，才能删除父表。", "三大删除命令对比：① ==`DROP TABLE`== 删除**表结构 + 全部数据**；② ==`TRUNCATE TABLE`== 保留表结构、一次性清空全部数据并重置 `AUTO_INCREMENT`（属 DDL）；③ ==`DELETE FROM 表名 [WHERE ...]`== 逐行删除满足条件的数据（属 DML，不删表结构）。"]}]'::jsonb, '', 'S2-2.4 删除表和数据库。 DROP 删除库表与 TRUNCATE / DELETE 区别 删除数据库：DROP DATABASE [IF EXISTS] 数据库名;（永久删除库及其中所有表）。 删除数据表：DROP TABLE [IF EXISTS] 表名;；若表被其他表的外键引用（父表），必须先删除子表或先解除外键约束，才能删除父表。 三大删除命令对比：① DROP TABLE 删除表结构 + 全部数据；② TRUNCATE TABLE 保留表结构、一次性清空全部数据并重置 AUTO_INCREMENT（属 DDL）；③ DELETE FROM 表名 [WHERE ...] 逐行删除满足条件的数据（属 DML，不删表结构）。', '{"pdf": "操作技能复习.pdf", "pages": [70]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-3.1 数据的插入、删除和修改处理。 (node_id=278)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (278, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (278, 1, '[{"id": "s2-3-1-b1", "t": "list", "imp": "core", "title": "DML 增删改（INSERT / UPDATE / DELETE）核心语法", "ordered": false, "items": ["插入数据（INSERT）：==`INSERT INTO 表名 (列1, 列2, ...) VALUES (值1, 值2, ...), (值1, 值2, ...);`==——可一次插入多行；字符串和日期值必须用单引号括起来。", "修改数据（UPDATE）：==`UPDATE 表名 SET 列1 = 值1, 列2 = 值2 WHERE 条件;`==——**若省略 `WHERE` 子句，将更新整张表的所有行**！", "删除数据（DELETE）：==`DELETE FROM 表名 WHERE 条件;`==——**若省略 `WHERE` 子句，将清空整张表的所有记录**（注意 `DELETE` 与 `FROM` 之间没有 `*` 号！）。"]}, {"id": "s2-3-1-b2", "t": "code", "imp": "important", "title": "INSERT / UPDATE / DELETE 综合书写范例", "lang": "sql", "code": "INSERT INTO student (sno, sname, age) VALUES (''202601'', ''张三'', 20), (''202602'', ''李四'', 21);\n\nUPDATE student SET age = age + 1 WHERE sno = ''202601'';\n\nDELETE FROM student WHERE age < 18;"}]'::jsonb, '', 'S2-3.1 数据的插入、删除和修改处理。 DML 增删改（INSERT / UPDATE / DELETE）核心语法 插入数据（INSERT）：INSERT INTO 表名 (列1, 列2, ...) VALUES (值1, 值2, ...), (值1, 值2, ...);——可一次插入多行；字符串和日期值必须用单引号括起来。 修改数据（UPDATE）：UPDATE 表名 SET 列1 = 值1, 列2 = 值2 WHERE 条件;——若省略 WHERE 子句，将更新整张表的所有行！ 删除数据（DELETE）：DELETE FROM 表名 WHERE 条件;——若省略 WHERE 子句，将清空整张表的所有记录（注意 DELETE 与 FROM 之间没有 * 号！）。 INSERT / UPDATE / DELETE 综合书写范例 INSERT INTO student (sno, sname, age) VALUES (''202601'', ''张三'', 20), (''202602'', ''李四'', 21);

UPDATE student SET age = age + 1 WHERE sno = ''202601'';

DELETE FROM student WHERE age < 18;', '{"pdf": "操作技能复习.pdf", "pages": [71]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-3.2 简单查询、连接查询。 (node_id=279)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (279, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (279, 1, '[{"id": "s2-3-2-b1", "t": "table", "imp": "core", "title": "WHERE 条件运算符与多表连接（JOIN）语法速查", "headers": ["查询类别", "关键字 / 语法格式", "高频考试要点与易错提示"], "rows": [["去重与别名", "`SELECT DISTINCT 列 AS 别名`", "`DISTINCT` 必须紧跟在 `SELECT` 之后，作用于所有选中列的组合"], ["范围与集合", "`BETWEEN a AND b`、`IN (v1, v2)`", "==`BETWEEN a AND b` 包含两端边界 `[a, b]`==（等价于 `>= a AND <= b`）"], ["模糊匹配 `LIKE`", "通配符 ==`%`（任意 0 或多个字符）==、==`_`（恰好 1 个字符）==", "姓张：`sname LIKE ''张%''`；姓张且两字姓名：==`sname LIKE ''张_''`=="], ["空值判断", "==`IS NULL` / `IS NOT NULL`==", "**严禁写成 `= NULL` 或 `!= NULL`**（结果恒为 UNKNOWN）"], ["内连接 `INNER JOIN`", "`FROM A [INNER] JOIN B ON A.id = B.a_id`", "仅返回两表中满足连接条件 `ON` 的匹配行（忘写 `ON` 会产生笛卡尔积）"], ["左/右外连接", "==`LEFT [OUTER] JOIN`== / `RIGHT [OUTER] JOIN`", "左连接保留**左表全部行**，右表无匹配时对应列填 `NULL`（常用于查“未选课学生”）"]]}]'::jsonb, '', 'S2-3.2 简单查询、连接查询。 WHERE 条件运算符与多表连接（JOIN）语法速查 查询类别 关键字 / 语法格式 高频考试要点与易错提示 去重与别名 SELECT DISTINCT 列 AS 别名 DISTINCT 必须紧跟在 SELECT 之后，作用于所有选中列的组合 范围与集合 BETWEEN a AND b、IN (v1, v2) BETWEEN a AND b 包含两端边界 [a, b]（等价于 >= a AND <= b） 模糊匹配 LIKE 通配符 %（任意 0 或多个字符）、_（恰好 1 个字符） 姓张：sname LIKE ''张%''；姓张且两字姓名：sname LIKE ''张_'' 空值判断 IS NULL / IS NOT NULL 严禁写成 = NULL 或 != NULL（结果恒为 UNKNOWN） 内连接 INNER JOIN FROM A [INNER] JOIN B ON A.id = B.a_id 仅返回两表中满足连接条件 ON 的匹配行（忘写 ON 会产生笛卡尔积） 左/右外连接 LEFT [OUTER] JOIN / RIGHT [OUTER] JOIN 左连接保留左表全部行，右表无匹配时对应列填 NULL（常用于查“未选课学生”）', '{"pdf": "操作技能复习.pdf", "pages": [72, 73, 74]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-3.3 嵌套子查询。 (node_id=280)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (280, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (280, 1, '[{"id": "s2-3-3-b1", "t": "list", "imp": "core", "title": "IN / 比较运算符 / ANY / ALL / EXISTS 嵌套子查询规则", "ordered": false, "items": ["标量子查询（返回单行单列）：可直接用 `=  >  <  >=  <=` 连接，如查高于平均分的学生：`WHERE score > (SELECT AVG(score) FROM sc)`。", "列子查询（返回多行一列）：必须配 ==`IN` / `NOT IN`== 或 `ANY` / `ALL`，绝不能直接用 `=`！其中 ==`> ALL(...)` 等价于大于最大值==，==`> ANY(...)` 等价于大于最小值==。", "存在性子查询 `EXISTS`：`WHERE EXISTS (子查询)` 只判断子查询**是否返回至少一行记录**（返回真/假），不关心具体列值。"]}, {"id": "s2-3-3-b2", "t": "code", "imp": "important", "title": "嵌套子查询典型大题写法", "lang": "sql", "code": "-- 查询选修了“数据库”课程的学生姓名\nSELECT sname FROM student\n WHERE sno IN (\n   SELECT sno FROM sc\n    WHERE cno = (SELECT cno FROM course WHERE cname = ''数据库'')\n );"}]'::jsonb, '', 'S2-3.3 嵌套子查询。 IN / 比较运算符 / ANY / ALL / EXISTS 嵌套子查询规则 标量子查询（返回单行单列）：可直接用 =  >  <  >=  <= 连接，如查高于平均分的学生：WHERE score > (SELECT AVG(score) FROM sc)。 列子查询（返回多行一列）：必须配 IN / NOT IN 或 ANY / ALL，绝不能直接用 =！其中 > ALL(...) 等价于大于最大值，> ANY(...) 等价于大于最小值。 存在性子查询 EXISTS：WHERE EXISTS (子查询) 只判断子查询是否返回至少一行记录（返回真/假），不关心具体列值。 嵌套子查询典型大题写法 -- 查询选修了“数据库”课程的学生姓名
SELECT sname FROM student
 WHERE sno IN (
   SELECT sno FROM sc
    WHERE cno = (SELECT cno FROM course WHERE cname = ''数据库'')
 );', '{"pdf": "操作技能复习.pdf", "pages": [75]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-3.4 对查询结果进行排序、计算及分组。 (node_id=281)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (281, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (281, 1, '[{"id": "s2-3-4-b1", "t": "list", "imp": "core", "title": "GROUP BY 分组、HAVING 筛选、ORDER BY 排序与 LIMIT 分页", "ordered": false, "items": ["SELECT 子句完整书写顺序：==`SELECT ... FROM ... WHERE ... GROUP BY ... HAVING ... ORDER BY ... LIMIT ...;`==", "`WHERE` vs `HAVING`（高频必考）：==`WHERE` 在分组前对原始行过滤，内部绝不能出现聚合函数==；==`HAVING` 在 `GROUP BY` 分组后对分组结果过滤，支持使用聚合函数==（如 `HAVING AVG(score) >= 80`）。", "排序 `ORDER BY`：==`ASC` 升序（默认，可省略）==，==`DESC` 降序==；多列排序如 `ORDER BY dept_id ASC, score DESC`（先按部门升序，同部门按成绩降序）。", "限制条数 `LIMIT`：`LIMIT n` 取前 `n` 条；==`LIMIT offset, count` 从偏移量 `offset`（从 0 开始计！）起取 `count` 条记录==。"]}]'::jsonb, '', 'S2-3.4 对查询结果进行排序、计算及分组。 GROUP BY 分组、HAVING 筛选、ORDER BY 排序与 LIMIT 分页 SELECT 子句完整书写顺序：SELECT ... FROM ... WHERE ... GROUP BY ... HAVING ... ORDER BY ... LIMIT ...; WHERE vs HAVING（高频必考）：WHERE 在分组前对原始行过滤，内部绝不能出现聚合函数；HAVING 在 GROUP BY 分组后对分组结果过滤，支持使用聚合函数（如 HAVING AVG(score) >= 80）。 排序 ORDER BY：ASC 升序（默认，可省略），DESC 降序；多列排序如 ORDER BY dept_id ASC, score DESC（先按部门升序，同部门按成绩降序）。 限制条数 LIMIT：LIMIT n 取前 n 条；LIMIT offset, count 从偏移量 offset（从 0 开始计！）起取 count 条记录。', '{"pdf": "操作技能复习.pdf", "pages": [76]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-3.5 求和、统计、求平均等常用函数在查询操作中的应用。 (node_id=282)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (282, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (282, 1, '[{"id": "s2-3-5-b1", "t": "table", "imp": "core", "title": "五大聚合函数与常用标量函数速查", "headers": ["函数名称", "功能说明", "NULL 值处理与必考细节"], "rows": [["==`COUNT(*)` vs `COUNT(列名)`==", "统计总行数 vs 统计该列非空值个数", "`COUNT(*)` 统计所有行（含 `NULL`）；==`COUNT(列名)` 自动忽略 `NULL` 值=="], ["==`SUM(列)` / `AVG(列)`==", "求和 / 求算术平均值", "仅用于数值列，自动忽略 `NULL` 行"], ["==`MAX(列)` / `MIN(列)`==", "求最大值 / 最小值", "可用于数值、字符串或日期列，忽略 `NULL`"], ["`CONCAT(s1, s2)` / `SUBSTRING(s, pos, len)`", "字符串拼接 / 截取子串", "**SQL 中字符串下标 `pos` 从 `1` 开始**（不同于 C 语言从 0 开始）"], ["`NOW()` / `CURDATE()` / `YEAR(d)`", "当前日期时间 / 当前日期 / 提取年份", "算年龄常用：`YEAR(CURDATE()) - YEAR(birth_date)`"]]}]'::jsonb, '', 'S2-3.5 求和、统计、求平均等常用函数在查询操作中的应用。 五大聚合函数与常用标量函数速查 函数名称 功能说明 NULL 值处理与必考细节 COUNT(*) vs COUNT(列名) 统计总行数 vs 统计该列非空值个数 COUNT(*) 统计所有行（含 NULL）；COUNT(列名) 自动忽略 NULL 值 SUM(列) / AVG(列) 求和 / 求算术平均值 仅用于数值列，自动忽略 NULL 行 MAX(列) / MIN(列) 求最大值 / 最小值 可用于数值、字符串或日期列，忽略 NULL CONCAT(s1, s2) / SUBSTRING(s, pos, len) 字符串拼接 / 截取子串 SQL 中字符串下标 pos 从 1 开始（不同于 C 语言从 0 开始） NOW() / CURDATE() / YEAR(d) 当前日期时间 / 当前日期 / 提取年份 算年龄常用：YEAR(CURDATE()) - YEAR(birth_date)', '{"pdf": "操作技能复习.pdf", "pages": [77, 78, 79]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-4.1 创建和查看视图。 (node_id=284)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (284, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (284, 1, '[{"id": "s2-4-1-b1", "t": "list", "imp": "core", "title": "视图（View）的本质、创建、查看与删除语法", "ordered": false, "items": ["视图的本质：视图是从一张或多张基本表导出的==虚拟表==，数据库中**只存放视图的定义（SELECT 查询语句），不存放视图对应的数据**；基本表数据变化会自动反映到视图中。", "创建或替换视图：==`CREATE [OR REPLACE] VIEW 视图名[(列名列表)] AS SELECT查询语句 [WITH CHECK OPTION];`==（其中 `WITH CHECK OPTION` 保证通过视图增删改时必须满足视图的 `WHERE` 条件）。", "查看与删除视图：`DESCRIBE 视图名;` 或 `SHOW CREATE VIEW 视图名;` 查看定义；==`DROP VIEW [IF EXISTS] 视图名;`== 删除视图。"]}]'::jsonb, '', 'S2-4.1 创建和查看视图。 视图（View）的本质、创建、查看与删除语法 视图的本质：视图是从一张或多张基本表导出的虚拟表，数据库中只存放视图的定义（SELECT 查询语句），不存放视图对应的数据；基本表数据变化会自动反映到视图中。 创建或替换视图：CREATE [OR REPLACE] VIEW 视图名[(列名列表)] AS SELECT查询语句 [WITH CHECK OPTION];（其中 WITH CHECK OPTION 保证通过视图增删改时必须满足视图的 WHERE 条件）。 查看与删除视图：DESCRIBE 视图名; 或 SHOW CREATE VIEW 视图名; 查看定义；DROP VIEW [IF EXISTS] 视图名; 删除视图。', '{"pdf": "操作技能复习.pdf", "pages": [80]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-4.2 用视图检索和修改基本表中数据。 (node_id=285)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (285, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (285, 1, '[{"id": "s2-4-2-b1", "t": "list", "imp": "core", "title": "视图查询与不可更新视图的判定条件", "ordered": false, "items": ["通过视图查询：语法与查询普通表完全一致（`SELECT * FROM 视图名 WHERE ...;`），系统在底层自动合并视图定义查询基本表。", "不可更新视图（必考判断）：若视图定义中包含 ==聚合函数（`SUM/AVG/COUNT/MAX/MIN`）、`DISTINCT`、`GROUP BY`、`HAVING`、`UNION`== 或算术表达式计算列，则**不能对该视图执行 `INSERT / UPDATE / DELETE`**。"]}]'::jsonb, '', 'S2-4.2 用视图检索和修改基本表中数据。 视图查询与不可更新视图的判定条件 通过视图查询：语法与查询普通表完全一致（SELECT * FROM 视图名 WHERE ...;），系统在底层自动合并视图定义查询基本表。 不可更新视图（必考判断）：若视图定义中包含 聚合函数（SUM/AVG/COUNT/MAX/MIN）、DISTINCT、GROUP BY、HAVING、UNION 或算术表达式计算列，则不能对该视图执行 INSERT / UPDATE / DELETE。', '{"pdf": "操作技能复习.pdf", "pages": [81]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S2-4.3 创建索引。 (node_id=286)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (286, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (286, 1, '[{"id": "s2-4-3-b1", "t": "list", "imp": "core", "title": "索引的作用、分类与创建/删除语法", "ordered": false, "items": ["索引的利弊：索引能==大幅加快 `SELECT` 查询、连接与排序速度==，但会**占用额外磁盘空间，并降低 `INSERT / UPDATE / DELETE` 的写操作速度**（需同步维护索引树）。", "创建索引三种方式：① ==`CREATE [UNIQUE | FULLTEXT] INDEX 索引名 ON 表名(列名 [ASC|DESC]);`==；② `ALTER TABLE 表名 ADD [UNIQUE] INDEX 索引名(列名);`；③ 建表时在 `CREATE TABLE` 内写 `INDEX 索引名(列名)`。", "查看与删除索引：==`SHOW INDEX FROM 表名;`== 查看表上的索引；==`DROP INDEX 索引名 ON 表名;`== 或 `ALTER TABLE 表名 DROP INDEX 索引名;` 删除索引。"]}]'::jsonb, '', 'S2-4.3 创建索引。 索引的作用、分类与创建/删除语法 索引的利弊：索引能大幅加快 SELECT 查询、连接与排序速度，但会占用额外磁盘空间，并降低 INSERT / UPDATE / DELETE 的写操作速度（需同步维护索引树）。 创建索引三种方式：① CREATE [UNIQUE | FULLTEXT] INDEX 索引名 ON 表名(列名 [ASC|DESC]);；② ALTER TABLE 表名 ADD [UNIQUE] INDEX 索引名(列名);；③ 建表时在 CREATE TABLE 内写 INDEX 索引名(列名)。 查看与删除索引：SHOW INDEX FROM 表名; 查看表上的索引；DROP INDEX 索引名 ON 表名; 或 ALTER TABLE 表名 DROP INDEX 索引名; 删除索引。', '{"pdf": "操作技能复习.pdf", "pages": [82, 83]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-1.1 参与者、用例的基本概念。 (node_id=288)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (288, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (288, 1, '[{"id": "s3-1-1-b1", "t": "list", "imp": "core", "title": "用例图三大核心元素（参与者、用例、系统边界）", "ordered": false, "items": ["参与者（Actor，画成==小人图标==）：在**系统外部**与系统直接交互的人、外部硬件设备或外部其他系统（注意：**参与者代表“角色”而非具体某个人，且绝对不属于系统内部**）。", "用例（Use Case，画成==椭圆==）：系统为参与者提供的**一项完整且有业务价值的功能服务**（动宾短语命名，如“借阅图书”、“查询成绩”）。", "系统边界（System Boundary，画成==矩形框==）：将系统内部的**用例**框在矩形内，而将**参与者**画在矩形框外部。"]}]'::jsonb, '', 'S3-1.1 参与者、用例的基本概念。 用例图三大核心元素（参与者、用例、系统边界） 参与者（Actor，画成小人图标）：在系统外部与系统直接交互的人、外部硬件设备或外部其他系统（注意：参与者代表“角色”而非具体某个人，且绝对不属于系统内部）。 用例（Use Case，画成椭圆）：系统为参与者提供的一项完整且有业务价值的功能服务（动宾短语命名，如“借阅图书”、“查询成绩”）。 系统边界（System Boundary，画成矩形框）：将系统内部的用例框在矩形内，而将参与者画在矩形框外部。', '{"pdf": "操作技能复习.pdf", "pages": [87]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-1.2 用例描述的格式要求。 (node_id=289)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (289, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (289, 1, '[{"id": "s3-1-2-b1", "t": "table", "imp": "core", "title": "标准用例规约（用例描述表）核心栏目要求", "headers": ["栏目名称", "填写内容与规范说明"], "rows": [["**用例名称 / 编号**", "与用例图椭圆中的动宾名称严格一致（如 `UC01 用户登录`）"], ["**参与者（Actor）**", "启动或参与该用例的主参与者与次参与者"], ["==前置条件（Precondition）==", "执行该用例之前，系统**必须已经满足的状态**（如“用户已成功登录系统”）"], ["==基本事件流（主成功场景）==", "正常情况下参与者与系统一步步交互的编号步骤序列"], ["==备选事件流（扩展/异常流）==", "分支情况、输入错误或异常分支的处理步骤（如“密码错误提示重试”）"], ["==后置条件（Postcondition）==", "用例执行结束后系统达到的最终状态或持久化结果（如“生成订单记录并扣减库存”）"]]}]'::jsonb, '', 'S3-1.2 用例描述的格式要求。 标准用例规约（用例描述表）核心栏目要求 栏目名称 填写内容与规范说明 用例名称 / 编号 与用例图椭圆中的动宾名称严格一致（如 UC01 用户登录） 参与者（Actor） 启动或参与该用例的主参与者与次参与者 前置条件（Precondition） 执行该用例之前，系统必须已经满足的状态（如“用户已成功登录系统”） 基本事件流（主成功场景） 正常情况下参与者与系统一步步交互的编号步骤序列 备选事件流（扩展/异常流） 分支情况、输入错误或异常分支的处理步骤（如“密码错误提示重试”） 后置条件（Postcondition） 用例执行结束后系统达到的最终状态或持久化结果（如“生成订单记录并扣减库存”）', '{"pdf": "操作技能复习.pdf", "pages": [87, 88]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-1.3 绘制用例图。 (node_id=290)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (290, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (290, 1, '[{"id": "s3-1-3-b1", "t": "table", "imp": "core", "title": "用例图四种关系、图形箭头方向与必考区分（重中之重）", "headers": ["关系类型", "图形表示法", "箭头指向规则（高频考点）", "典型语义与真题例子"], "rows": [["**关联（Association）**", "实线（无箭头或带箭头）", "连接**参与者**与**用例**", "表示参与者参与该用例交互"], ["**泛化（Generalization）**", "实线 + **空心三角箭头**", "==子参与者/子用例 → 父参与者/父用例==", "特殊与一般继承关系（如“VIP会员”指向“普通会员”）"], ["==包含（Include）==", "虚线箭头 + **`<<include>>`**", "==基用例 → 被包含公共子用例==", "**必须执行**的公共步骤（如“取款”、“转账”都 `<<include>>` 指向“验证密码”）"], ["==扩展（Extend）==", "虚线箭头 + **`<<extend>>`**", "==扩展用例 → 基用例（箭头方向与 include 相反！）==", "**特定条件下可选执行**的附加功能（如“打印回单” `<<extend>>` 指向“取款”）"]]}]'::jsonb, '', 'S3-1.3 绘制用例图。 用例图四种关系、图形箭头方向与必考区分（重中之重） 关系类型 图形表示法 箭头指向规则（高频考点） 典型语义与真题例子 关联（Association） 实线（无箭头或带箭头） 连接参与者与用例 表示参与者参与该用例交互 泛化（Generalization） 实线 + 空心三角箭头 子参与者/子用例 → 父参与者/父用例 特殊与一般继承关系（如“VIP会员”指向“普通会员”） 包含（Include） 虚线箭头 + <<include>> 基用例 → 被包含公共子用例 必须执行的公共步骤（如“取款”、“转账”都 <<include>> 指向“验证密码”） 扩展（Extend） 虚线箭头 + <<extend>> 扩展用例 → 基用例（箭头方向与 include 相反！） 特定条件下可选执行的附加功能（如“打印回单” <<extend>> 指向“取款”）', '{"pdf": "操作技能复习.pdf", "pages": [88]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-2.1 类图的基本概念。 (node_id=292)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (292, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (292, 1, '[{"id": "s3-2-1-b1", "t": "list", "imp": "core", "title": "UML 类的三层分格矩形与可见性符号", "ordered": false, "items": ["三层矩形框结构：第一层写**类名**（抽象类名用斜体）；第二层写**属性（Attributes）**，格式为 `可见性 属性名 : 类型 [= 默认值]`；第三层写**操作/方法（Operations）**，格式为 `可见性 方法名(参数列表) : 返回类型`。", "四种可见性符号（必记）：==`+` 表示 `public`（公有）==、==`-` 表示 `private`（私有）==、==`#` 表示 `protected`（受保护）==、==`~` 表示 `package`（包内可见）==。"]}]'::jsonb, '', 'S3-2.1 类图的基本概念。 UML 类的三层分格矩形与可见性符号 三层矩形框结构：第一层写类名（抽象类名用斜体）；第二层写属性（Attributes），格式为 可见性 属性名 : 类型 [= 默认值]；第三层写操作/方法（Operations），格式为 可见性 方法名(参数列表) : 返回类型。 四种可见性符号（必记）：+ 表示 public（公有）、- 表示 private（私有）、# 表示 protected（受保护）、~ 表示 package（包内可见）。', '{"pdf": "操作技能复习.pdf", "pages": [89]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-2.2 分析识别类，绘制类图。 (node_id=293)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (293, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (293, 1, '[{"id": "s3-2-2-b1", "t": "table", "imp": "core", "title": "类图六大关系与图形符号对比（耦合度由弱到强）", "headers": ["关系名称", "UML 图形符号与箭头方向", "核心语义与典型示例"], "rows": [["**依赖（Dependency）**", "==虚线 + 开放箭头 `--->`==（指向被依赖类）", "临时使用关系，常作为方法局部变量或参数（如“人”依赖“工具”）"], ["**关联（Association）**", "==实线==（可带开放箭头，两端标多重性如 `1`、`0..*`、`1..*`）", "长期拥有的结构关系，常体现为成员变量（如“教师”与“学生”）"], ["==聚合（Aggregation）==", "==空心菱形 + 实线==（**空心菱形在整体端**）", "整体与部分关系，==部分可以脱离整体独立存在==（如“球队”与“球员”、“汽车”与“轮胎”）"], ["==组合（Composition）==", "==实心菱形 + 实线==（**实心菱形在整体端**）", "强整体与部分，==同生共死，部分不能脱离整体存在==（如“公司”与“部门”、“窗口”与“菜单”）"], ["**泛化（继承）**", "==实线 + 空心三角箭头==（子类指向父类）", "`is-a` 继承关系（如“轿车”继承“汽车”）"], ["**实现（Realization）**", "==虚线 + 空心三角箭头==（实现类指向接口）", "类实现接口（Interface）契约"]]}]'::jsonb, '', 'S3-2.2 分析识别类，绘制类图。 类图六大关系与图形符号对比（耦合度由弱到强） 关系名称 UML 图形符号与箭头方向 核心语义与典型示例 依赖（Dependency） 虚线 + 开放箭头 --->（指向被依赖类） 临时使用关系，常作为方法局部变量或参数（如“人”依赖“工具”） 关联（Association） 实线（可带开放箭头，两端标多重性如 1、0..*、1..*） 长期拥有的结构关系，常体现为成员变量（如“教师”与“学生”） 聚合（Aggregation） 空心菱形 + 实线（空心菱形在整体端） 整体与部分关系，部分可以脱离整体独立存在（如“球队”与“球员”、“汽车”与“轮胎”） 组合（Composition） 实心菱形 + 实线（实心菱形在整体端） 强整体与部分，同生共死，部分不能脱离整体存在（如“公司”与“部门”、“窗口”与“菜单”） 泛化（继承） 实线 + 空心三角箭头（子类指向父类） is-a 继承关系（如“轿车”继承“汽车”） 实现（Realization） 虚线 + 空心三角箭头（实现类指向接口） 类实现接口（Interface）契约', '{"pdf": "操作技能复习.pdf", "pages": [90, 91, 92, 93, 94, 95]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-2.3 绘制对象图。 (node_id=294)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (294, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (294, 1, '[{"id": "s3-2-3-b1", "t": "list", "imp": "core", "title": "对象图（Object Diagram）与类图的区别及表示法", "ordered": false, "items": ["对象图的定义：对象图是类图在**某一特定时刻的静态实例快照**。", "图形特征（必记）：① 对象名必须**加下划线**，格式为 ==`<u>对象名 : 类名</u>`==（匿名对象写 `<u>: 类名</u>`）；② 对象框只有**两层**（第一层带下划线的对象名，第二层写属性的具体取值如 `age = 20`，**不包含方法层**）；③ 对象之间的连线称为**链（Link）**，不标多重性数字。"]}]'::jsonb, '', 'S3-2.3 绘制对象图。 对象图（Object Diagram）与类图的区别及表示法 对象图的定义：对象图是类图在某一特定时刻的静态实例快照。 图形特征（必记）：① 对象名必须加下划线，格式为 <u>对象名 : 类名</u>（匿名对象写 <u>: 类名</u>）；② 对象框只有两层（第一层带下划线的对象名，第二层写属性的具体取值如 age = 20，不包含方法层）；③ 对象之间的连线称为链（Link），不标多重性数字。', '{"pdf": "操作技能复习.pdf", "pages": [96]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-3.1 顺序图的组成。 (node_id=296)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (296, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (296, 1, '[{"id": "s3-3-1-b1", "t": "list", "imp": "core", "title": "顺序图（时序图 Sequence Diagram）二维结构与核心元素", "ordered": false, "items": ["二维坐标含义：强调消息的==时间先后顺序==——**水平方向**排列参与交互的各个对象，**垂直方向（自上而下）**表示时间的流逝。", "四大组成元素：① **对象/角色**（顶部矩形框 `<u>对象名:类名</u>` 或小人）；② ==生命线（Lifeline）==（对象下方垂直延伸的**虚线**，表示对象存在的时间段）；③ ==激活期/控制焦点（Activation）==（生命线上的**窄长条矩形**，表示对象正在执行某项操作）；④ **消息（Message）**（连接生命线的水平带箭头连线）。"]}]'::jsonb, '', 'S3-3.1 顺序图的组成。 顺序图（时序图 Sequence Diagram）二维结构与核心元素 二维坐标含义：强调消息的时间先后顺序——水平方向排列参与交互的各个对象，垂直方向（自上而下）表示时间的流逝。 四大组成元素：① 对象/角色（顶部矩形框 <u>对象名:类名</u> 或小人）；② 生命线（Lifeline）（对象下方垂直延伸的虚线，表示对象存在的时间段）；③ 激活期/控制焦点（Activation）（生命线上的窄长条矩形，表示对象正在执行某项操作）；④ 消息（Message）（连接生命线的水平带箭头连线）。', '{"pdf": "操作技能复习.pdf", "pages": [97, 98]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-3.2 顺序图中的消息类型。 (node_id=297)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (297, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (297, 1, '[{"id": "s3-3-2-b1", "t": "table", "imp": "core", "title": "顺序图三大消息类型与箭头符号对照（必背）", "headers": ["消息类型", "UML 箭头样式", "交互语义"], "rows": [["==同步消息（Synchronous）==", "==实线 + 实心三角箭头==", "发送者发出消息后**必须阻塞等待**接收者处理完毕并返回后，才继续往下执行"], ["==异步消息（Asynchronous）==", "==实线 + 开放线形箭头（`->`）==", "发送者发出消息后**不等待返回**，立即继续执行后续操作"], ["==返回消息（Reply / Return）==", "==虚线 + 开放线形箭头（`<--`）==", "表示同步调用执行结束，向调用方返回处理结果"]]}]'::jsonb, '', 'S3-3.2 顺序图中的消息类型。 顺序图三大消息类型与箭头符号对照（必背） 消息类型 UML 箭头样式 交互语义 同步消息（Synchronous） 实线 + 实心三角箭头 发送者发出消息后必须阻塞等待接收者处理完毕并返回后，才继续往下执行 异步消息（Asynchronous） 实线 + 开放线形箭头（->） 发送者发出消息后不等待返回，立即继续执行后续操作 返回消息（Reply / Return） 虚线 + 开放线形箭头（<--） 表示同步调用执行结束，向调用方返回处理结果', '{"pdf": "操作技能复习.pdf", "pages": [99]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-3.3 绘制顺序图。 (node_id=298)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (298, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (298, 1, '[{"id": "s3-3-3-b1", "t": "list", "imp": "core", "title": "绘制顺序图的步骤与组合片段（alt / opt / loop）", "ordered": false, "items": ["绘制步骤：① 确定交互上下文与参与对象（从左到右常按：**参与者 → 边界类/界面 → 控制类 → 实体类**排列）；② 沿时间轴自上而下依次画出请求消息、自调用消息与返回消息。", "常用组合片段框：==`opt`==（可选单分支，相当 `if`）、==`alt`==（多分支互斥，相当 `if-else`）、==`loop`==（循环重复执行）、`par`（并行执行）。"]}]'::jsonb, '', 'S3-3.3 绘制顺序图。 绘制顺序图的步骤与组合片段（alt / opt / loop） 绘制步骤：① 确定交互上下文与参与对象（从左到右常按：参与者 → 边界类/界面 → 控制类 → 实体类排列）；② 沿时间轴自上而下依次画出请求消息、自调用消息与返回消息。 常用组合片段框：opt（可选单分支，相当 if）、alt（多分支互斥，相当 if-else）、loop（循环重复执行）、par（并行执行）。', '{"pdf": "操作技能复习.pdf", "pages": [100]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-4.1 状态机的含义。 (node_id=300)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (300, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (300, 1, '[{"id": "s3-4-1-b1", "t": "list", "imp": "core", "title": "状态机与状态图的核心概念", "ordered": false, "items": ["状态图的关注点：状态图用于描述**单个对象在其生命周期内**响应外部事件所经历的==状态序列以及状态之间的转移（Transition）==（顺序图描述多对象间交互，状态图聚焦单对象内部状态变迁）。", "状态（State）：对象在生命周期中满足某些条件、执行某些活动或等待某些事件时的稳定状况（如订单的“待支付”、“已发货”、“已完成”）。"]}]'::jsonb, '', 'S3-4.1 状态机的含义。 状态机与状态图的核心概念 状态图的关注点：状态图用于描述单个对象在其生命周期内响应外部事件所经历的状态序列以及状态之间的转移（Transition）（顺序图描述多对象间交互，状态图聚焦单对象内部状态变迁）。 状态（State）：对象在生命周期中满足某些条件、执行某些活动或等待某些事件时的稳定状况（如订单的“待支付”、“已发货”、“已完成”）。', '{"pdf": "操作技能复习.pdf", "pages": [101]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-4.2 状态机图中的基本标记符。 (node_id=301)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (301, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (301, 1, '[{"id": "s3-4-2-b1", "t": "table", "imp": "core", "title": "状态图四大基本符号与转移标签语法", "headers": ["元素名称", "UML 图形表示", "语法与必记规则"], "rows": [["==初态（初始状态）==", "==实心黑圆点 `●`==", "每个状态图**最多只有 1 个初态**，只有出边没有入边"], ["==终态（终止状态）==", "==牛眼符 `◉`（圆圈内套实心圆点）==", "表示对象生命周期结束，可有 0 个或多个终态，只有入边没有出边"], ["**普通状态**", "==圆角矩形框==", "分格显示状态名、内部活动（`entry / 动作`、`do / 活动`、`exit / 动作`）"], ["**转移（Transition）**", "**带箭头的实线**", "连线标准标签格式：==`事件名 [监护条件] / 动作表达式`==（三部分均可按需省略）"]]}]'::jsonb, '', 'S3-4.2 状态机图中的基本标记符。 状态图四大基本符号与转移标签语法 元素名称 UML 图形表示 语法与必记规则 初态（初始状态） 实心黑圆点 ● 每个状态图最多只有 1 个初态，只有出边没有入边 终态（终止状态） 牛眼符 ◉（圆圈内套实心圆点） 表示对象生命周期结束，可有 0 个或多个终态，只有入边没有出边 普通状态 圆角矩形框 分格显示状态名、内部活动（entry / 动作、do / 活动、exit / 动作） 转移（Transition） 带箭头的实线 连线标准标签格式：事件名 [监护条件] / 动作表达式（三部分均可按需省略）', '{"pdf": "操作技能复习.pdf", "pages": [101]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S3-4.3 绘制状态图。 (node_id=302)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (302, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (302, 1, '[{"id": "s3-4-3-b1", "t": "list", "imp": "core", "title": "状态图绘制流程与内部活动（entry / do / exit）区分", "ordered": false, "items": ["状态内部三类活动：① ==`entry / 动作`== 进入该状态瞬间立即执行的原子动作；② ==`do / 活动`== 处于该状态期间持续执行的活动；③ ==`exit / 动作`== 离开该状态瞬间执行的动作。", "监护条件（Guard Condition）：写在方括号 `[条件]` 中，只有当触发事件发生**且监护条件为真**时，状态转移才会发生。"]}]'::jsonb, '', 'S3-4.3 绘制状态图。 状态图绘制流程与内部活动（entry / do / exit）区分 状态内部三类活动：① entry / 动作 进入该状态瞬间立即执行的原子动作；② do / 活动 处于该状态期间持续执行的活动；③ exit / 动作 离开该状态瞬间执行的动作。 监护条件（Guard Condition）：写在方括号 [条件] 中，只有当触发事件发生且监护条件为真时，状态转移才会发生。', '{"pdf": "操作技能复习.pdf", "pages": [102, 103]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-1.1 根据实际应用场景选择合适的拓扑结构。 (node_id=304)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (304, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (304, 1, '[{"id": "s4-1-1-b1", "t": "table", "imp": "core", "title": "局域网五大基本拓扑结构优缺点与适用场景对比", "headers": ["拓扑结构", "结构特征", "突出优点", "主要缺点与典型应用"], "rows": [["==星型拓扑==", "所有节点通过独立线缆连接到**中央节点（交换机/集线器）**", "==单站点故障不影响全网==，易于监控与扩展", "**中央节点一旦故障则全网瘫痪**；现代以太网（双绞线+交换机）首选"], ["**总线型拓扑**", "所有节点共享一条主干传输介质（如同轴电缆）", "布线简单、成本低", "主干线断路则全网瘫痪，故障定位难、高负载下冲突严重"], ["**环型拓扑**", "各节点首尾相连形成闭合环路，数据沿单向传输", "无路径选择问题", "环中任意一处节点或链路断开即导致全网中断（如令牌环网、FDDI）"], ["==树型拓扑==", "星型拓扑的层次化扩展（核心层—汇聚层—接入层）", "易于大规模分级扩展与故障隔离", "根/上层节点故障会影响整个下属分支；**园区网、校园网主流结构**"], ["==网状拓扑==", "节点之间有多条冗余链路互连", "==可靠性最高==，单链路断开可自动绕行", "建网与维护成本高；常用于广域网骨干或企业核心层双机热备"]]}]'::jsonb, '', 'S4-1.1 根据实际应用场景选择合适的拓扑结构。 局域网五大基本拓扑结构优缺点与适用场景对比 拓扑结构 结构特征 突出优点 主要缺点与典型应用 星型拓扑 所有节点通过独立线缆连接到中央节点（交换机/集线器） 单站点故障不影响全网，易于监控与扩展 中央节点一旦故障则全网瘫痪；现代以太网（双绞线+交换机）首选 总线型拓扑 所有节点共享一条主干传输介质（如同轴电缆） 布线简单、成本低 主干线断路则全网瘫痪，故障定位难、高负载下冲突严重 环型拓扑 各节点首尾相连形成闭合环路，数据沿单向传输 无路径选择问题 环中任意一处节点或链路断开即导致全网中断（如令牌环网、FDDI） 树型拓扑 星型拓扑的层次化扩展（核心层—汇聚层—接入层） 易于大规模分级扩展与故障隔离 根/上层节点故障会影响整个下属分支；园区网、校园网主流结构 网状拓扑 节点之间有多条冗余链路互连 可靠性最高，单链路断开可自动绕行 建网与维护成本高；常用于广域网骨干或企业核心层双机热备', '{"pdf": "操作技能复习.pdf", "pages": [105, 106]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-1.2 根据实际应用场景选择合适的交换机、路由器等网络设备。 (node_id=305)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (305, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (305, 1, '[{"id": "s4-1-2-b1", "t": "table", "imp": "core", "title": "网卡、集线器、交换机、路由器所在层次与冲突域/广播域隔离", "headers": ["网络设备", "OSI 层次", "寻址/转发依据", "隔离冲突域", "隔离广播域"], "rows": [["中继器 / 集线器 (Hub)", "==物理层 (L1)==", "比特流放大重发（共享带宽）", "**不隔离**（所有端口同属 1 个冲突域）", "不隔离"], ["网桥 / 二层交换机 (Switch)", "==数据链路层 (L2)==", "==MAC 地址表==（独享端口带宽）", "==隔离冲突域==（每个端口是独立冲突域）", "**不隔离广播域**（除非划分 VLAN）"], ["三层交换机 / 路由器 (Router)", "==网络层 (L3)==", "==IP 路由表==", "==隔离冲突域==", "==隔离广播域==（连接不同网段/异构网络）"]]}]'::jsonb, '', 'S4-1.2 根据实际应用场景选择合适的交换机、路由器等网络设备。 网卡、集线器、交换机、路由器所在层次与冲突域/广播域隔离 网络设备 OSI 层次 寻址/转发依据 隔离冲突域 隔离广播域 中继器 / 集线器 (Hub) 物理层 (L1) 比特流放大重发（共享带宽） 不隔离（所有端口同属 1 个冲突域） 不隔离 网桥 / 二层交换机 (Switch) 数据链路层 (L2) MAC 地址表（独享端口带宽） 隔离冲突域（每个端口是独立冲突域） 不隔离广播域（除非划分 VLAN） 三层交换机 / 路由器 (Router) 网络层 (L3) IP 路由表 隔离冲突域 隔离广播域（连接不同网段/异构网络）', '{"pdf": "操作技能复习.pdf", "pages": [107, 108]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-1.3 搭建有线局域网。 (node_id=306)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (306, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (306, 1, '[{"id": "s4-1-3-b1", "t": "list", "imp": "core", "title": "双绞线 T568A / T568B 线序标准、传输距离与连通测试", "ordered": false, "items": ["双绞线标准线序（1~8 脚必背）：① ==T568B（工程最常用）：白橙、橙、白绿、蓝、白蓝、绿、白棕、棕==；② ==T568A：白绿、绿、白橙、蓝、白蓝、橙、白棕、棕==（A 与 B 仅将 1/3、2/6 即橙绿两对调换）。", "直通线 vs 交叉线：两端同为 T568B 为**直通线**，用于连接==不同类设备==（如 PC—交换机、交换机—路由器）；一端 T568A 一端 T568B 为**交叉线**，用于连接==同类设备==（如 PC—PC、老式交换机—交换机，路由器和 PC 在此规则中视为同类三层设备）。", "双绞线最大有效传输距离：单段双绞线（Cat5e / Cat6，RJ-45 水晶头）最大传输距离为 ==100 米==。"]}]'::jsonb, '', 'S4-1.3 搭建有线局域网。 双绞线 T568A / T568B 线序标准、传输距离与连通测试 双绞线标准线序（1~8 脚必背）：① T568B（工程最常用）：白橙、橙、白绿、蓝、白蓝、绿、白棕、棕；② T568A：白绿、绿、白橙、蓝、白蓝、橙、白棕、棕（A 与 B 仅将 1/3、2/6 即橙绿两对调换）。 直通线 vs 交叉线：两端同为 T568B 为直通线，用于连接不同类设备（如 PC—交换机、交换机—路由器）；一端 T568A 一端 T568B 为交叉线，用于连接同类设备（如 PC—PC、老式交换机—交换机，路由器和 PC 在此规则中视为同类三层设备）。 双绞线最大有效传输距离：单段双绞线（Cat5e / Cat6，RJ-45 水晶头）最大传输距离为 100 米。', '{"pdf": "操作技能复习.pdf", "pages": [109, 110]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-2.1 根据实际应用场景选择合适的无线局域网的组网模式。 (node_id=308)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (308, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (308, 1, '[{"id": "s4-2-1-b1", "t": "table", "imp": "core", "title": "无线局域网（WLAN）两种组网模式与 IEEE 802.11 协议标准", "headers": ["模式 / 协议", "核心特征与工作频段", "典型应用场景"], "rows": [["==Ad-Hoc 模式（点对点/无中心）==", "无需无线 AP，无线终端（STA）之间直接对等通信（IBSS）", "会议室几台笔记本临时传文件"], ["==Infrastructure 模式（基础结构）==", "所有无线终端通过中央**无线访问接入点（AP / 无线路由器）**通信并与有线网桥接（BSS / ESS）", "家庭、企业、校园 Wi-Fi 覆盖"], ["**802.11a / b / g**", "`11a`（5GHz, 54Mbps）、`11b`（2.4GHz, 11Mbps）、`11g`（2.4GHz, 54Mbps）", "早期无线标准"], ["==802.11n (Wi-Fi 4) / 802.11ac (Wi-Fi 5) / 802.11ax (Wi-Fi 6)==", "`11n` 支持 **2.4G/5G 双频**；`11ac` 仅工作在 5GHz；`11ax` 支持 2.4G/5G 高并发", "现代主流高速无线网络；2.4GHz 互不干扰信道为 ==`1、6、11`=="]]}]'::jsonb, '', 'S4-2.1 根据实际应用场景选择合适的无线局域网的组网模式。 无线局域网（WLAN）两种组网模式与 IEEE 802.11 协议标准 模式 / 协议 核心特征与工作频段 典型应用场景 Ad-Hoc 模式（点对点/无中心） 无需无线 AP，无线终端（STA）之间直接对等通信（IBSS） 会议室几台笔记本临时传文件 Infrastructure 模式（基础结构） 所有无线终端通过中央无线访问接入点（AP / 无线路由器）通信并与有线网桥接（BSS / ESS） 家庭、企业、校园 Wi-Fi 覆盖 802.11a / b / g 11a（5GHz, 54Mbps）、11b（2.4GHz, 11Mbps）、11g（2.4GHz, 54Mbps） 早期无线标准 802.11n (Wi-Fi 4) / 802.11ac (Wi-Fi 5) / 802.11ax (Wi-Fi 6) 11n 支持 2.4G/5G 双频；11ac 仅工作在 5GHz；11ax 支持 2.4G/5G 高并发 现代主流高速无线网络；2.4GHz 互不干扰信道为 1、6、11', '{"pdf": "操作技能复习.pdf", "pages": [111, 112, 113, 114, 115]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-2.2 配置无线局域网的 SSID、安全类型和加密类型。 (node_id=309)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (309, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (309, 1, '[{"id": "s4-2-2-b1", "t": "list", "imp": "core", "title": "SSID 服务集标识与无线安全加密协议演进", "ordered": false, "items": ["SSID（Service Set Identifier，服务集标识符）：即 ==Wi-Fi 无线网络名称==（区分大小写，最长 32 个字符）；在无线路由器中关闭“SSID 广播”可隐藏无线网络名称，但客户端仍可手动输入 SSID 连接。", "安全认证与加密类型（安全性由低到高）：① `WEP`（有线等效加密，极易被破解，已淘汰）；② `WPA-PSK`（常用 `TKIP` 加密）；③ ==`WPA2-PSK` / `WPA3-PSK`（家用/办公首选，采用高强度 `AES` / `CCMP` 加密算法）==。"]}]'::jsonb, '', 'S4-2.2 配置无线局域网的 SSID、安全类型和加密类型。 SSID 服务集标识与无线安全加密协议演进 SSID（Service Set Identifier，服务集标识符）：即 Wi-Fi 无线网络名称（区分大小写，最长 32 个字符）；在无线路由器中关闭“SSID 广播”可隐藏无线网络名称，但客户端仍可手动输入 SSID 连接。 安全认证与加密类型（安全性由低到高）：① WEP（有线等效加密，极易被破解，已淘汰）；② WPA-PSK（常用 TKIP 加密）；③ WPA2-PSK / WPA3-PSK（家用/办公首选，采用高强度 AES / CCMP 加密算法）。', '{"pdf": "操作技能复习.pdf", "pages": [116, 117]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S4-2.3 搭建无线局域网。 (node_id=310)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (310, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (310, 1, '[{"id": "s4-2-3-b1", "t": "list", "imp": "core", "title": "家用/小型办公无线路由器 WAN 口与 LAN 口配置规范", "ordered": true, "items": ["物理接线：将光猫（Modem）或上级外网网线接入无线路由器的 ==`WAN` 口（广域网口，常为蓝色）==；局域网台式机接入 `LAN` 口（局域网口）。", "配置 WAN 口上网方式：家庭宽带拨号选 ==`PPPoE`==（输入运营商宽带账号密码）；上级已分配自动 IP 选 **动态 IP（DHCP）**；专线固定地址选 **静态 IP**。", "配置 LAN 口与 DHCP 服务：设置路由器管理 IP（如 `192.168.1.1`），开启 DHCP 服务器自动为无线客户端分配 IP、子网掩码、默认网关与 DNS（**注意：WAN 口与 LAN 口绝不能处于同一网段**）。"]}]'::jsonb, '', 'S4-2.3 搭建无线局域网。 家用/小型办公无线路由器 WAN 口与 LAN 口配置规范 物理接线：将光猫（Modem）或上级外网网线接入无线路由器的 WAN 口（广域网口，常为蓝色）；局域网台式机接入 LAN 口（局域网口）。 配置 WAN 口上网方式：家庭宽带拨号选 PPPoE（输入运营商宽带账号密码）；上级已分配自动 IP 选 动态 IP（DHCP）；专线固定地址选 静态 IP。 配置 LAN 口与 DHCP 服务：设置路由器管理 IP（如 192.168.1.1），开启 DHCP 服务器自动为无线客户端分配 IP、子网掩码、默认网关与 DNS（注意：WAN 口与 LAN 口绝不能处于同一网段）。', '{"pdf": "操作技能复习.pdf", "pages": [118]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-1.1 启动或关闭 Windows 功能。 (node_id=312)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (312, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (312, 1, '[{"id": "s5-1-1-b1", "t": "list", "imp": "core", "title": "启用或关闭 Windows 内置功能入口与典型组件", "ordered": false, "items": ["标准操作路径：打开【控制面板】→【程序】（或【程序和功能】）→ 点击左侧==【启用或关闭 Windows 功能】==；也可按 `Win + R` 输入 ==`optionalfeatures`== 直接打开。", "常见内置功能组件：可在此勾选开启 **Internet Information Services (IIS Web 服务器)**、**Telnet 客户端**、**Hyper-V 虚拟机平台**、**SMB 1.0/CIFS 文件共享支持** 等系统自带组件（无需外部安装包）。"]}]'::jsonb, '', 'S5-1.1 启动或关闭 Windows 功能。 启用或关闭 Windows 内置功能入口与典型组件 标准操作路径：打开【控制面板】→【程序】（或【程序和功能】）→ 点击左侧【启用或关闭 Windows 功能】；也可按 Win + R 输入 optionalfeatures 直接打开。 常见内置功能组件：可在此勾选开启 Internet Information Services (IIS Web 服务器)、Telnet 客户端、Hyper-V 虚拟机平台、SMB 1.0/CIFS 文件共享支持 等系统自带组件（无需外部安装包）。', '{"pdf": "操作技能复习.pdf", "pages": [120, 121]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-1.2 软件的安装、升级、卸载管理。 (node_id=313)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (313, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (313, 1, '[{"id": "s5-1-2-b1", "t": "list", "imp": "core", "title": "Windows 10 应用安装格式与正确卸载方式", "ordered": false, "items": ["常见安装包扩展名：可执行安装程序 ==`.exe`==、Windows Installer 安装包 ==`.msi`==、微软商店应用包 `.appx` / `.msix`。", "正确卸载软件的三种官方途径：① 【设置】(`Win + I`) →【应用】→【应用和功能】，选中软件点击【卸载】；② 【控制面板】→【程序和功能】（快捷键 `Win + R` 输入 ==`appwiz.cpl`==），右键软件选择【卸载】；③ 运行软件安装目录下的卸载程序 `uninst.exe` / `uninstall.exe`。", "禁忌提醒：==严禁直接将软件安装文件夹（如 `Program Files` 下的目录）拖入回收站删除==，否则会残留大量注册表项、系统服务和右键菜单垃圾。"]}]'::jsonb, '', 'S5-1.2 软件的安装、升级、卸载管理。 Windows 10 应用安装格式与正确卸载方式 常见安装包扩展名：可执行安装程序 .exe、Windows Installer 安装包 .msi、微软商店应用包 .appx / .msix。 正确卸载软件的三种官方途径：① 【设置】(Win + I) →【应用】→【应用和功能】，选中软件点击【卸载】；② 【控制面板】→【程序和功能】（快捷键 Win + R 输入 appwiz.cpl），右键软件选择【卸载】；③ 运行软件安装目录下的卸载程序 uninst.exe / uninstall.exe。 禁忌提醒：严禁直接将软件安装文件夹（如 Program Files 下的目录）拖入回收站删除，否则会残留大量注册表项、系统服务和右键菜单垃圾。', '{"pdf": "操作技能复习.pdf", "pages": [122, 123, 124, 125, 126]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-2.1 创建、删除本地或管理员账户。 (node_id=315)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (315, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (315, 1, '[{"id": "s5-2-1-b1", "t": "list", "imp": "core", "title": "Windows 10 内置账户、图形界面与 net user 命令行管理", "ordered": false, "items": ["三大内置本地账户：① ==`Administrator`==（内置最高权限系统管理员，Win10 默认禁用，且**该内置账户不能被删除**）；② ==`Guest`==（来宾账户，权限最低，默认禁用）；③ `DefaultAccount`。", "图形界面管理路径：① 【设置】→【账户】→【家庭和其他用户】添加不带 Microsoft 账户的本地用户；② 【计算机管理】（`compmgr.msc` 或 `lusrmgr.msc`）→【系统工具】→==【本地用户和组】→【用户】==。", "命令行快捷指令（管理员 CMD）：==`net user 用户名 密码 /add`== 创建本地用户；==`net user 用户名 /del`== 删除用户；==`net localgroup administrators 用户名 /add`== 将用户提权加入管理员组。"]}]'::jsonb, '', 'S5-2.1 创建、删除本地或管理员账户。 Windows 10 内置账户、图形界面与 net user 命令行管理 三大内置本地账户：① Administrator（内置最高权限系统管理员，Win10 默认禁用，且该内置账户不能被删除）；② Guest（来宾账户，权限最低，默认禁用）；③ DefaultAccount。 图形界面管理路径：① 【设置】→【账户】→【家庭和其他用户】添加不带 Microsoft 账户的本地用户；② 【计算机管理】（compmgr.msc 或 lusrmgr.msc）→【系统工具】→【本地用户和组】→【用户】。 命令行快捷指令（管理员 CMD）：net user 用户名 密码 /add 创建本地用户；net user 用户名 /del 删除用户；net localgroup administrators 用户名 /add 将用户提权加入管理员组。', '{"pdf": "操作技能复习.pdf", "pages": [127, 128, 129, 130]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-2.2 配置用户账户。 (node_id=316)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (316, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (316, 1, '[{"id": "s5-2-2-b1", "t": "list", "imp": "core", "title": "账户类型切换（标准用户 vs 管理员）与密码策略配置", "ordered": false, "items": ["两种账户类型权限区别：==管理员（Administrator）==可安装全局软件、修改系统配置与管理其他账户；==标准用户（Standard User）==只能使用已安装软件、修改自身个人设置，不能更改影响其他用户的系统级设置。", "本地用户属性配置（`lusrmgr.msc`）：双击用户名可勾选【用户下次登录时须更改密码】、【用户不能更改密码】、==【密码永不过期】==、==【账户已禁用】==（临时停用某账号而不删除其文件时，应选“账户已禁用”）。"]}]'::jsonb, '', 'S5-2.2 配置用户账户。 账户类型切换（标准用户 vs 管理员）与密码策略配置 两种账户类型权限区别：管理员（Administrator）可安装全局软件、修改系统配置与管理其他账户；标准用户（Standard User）只能使用已安装软件、修改自身个人设置，不能更改影响其他用户的系统级设置。 本地用户属性配置（lusrmgr.msc）：双击用户名可勾选【用户下次登录时须更改密码】、【用户不能更改密码】、【密码永不过期】、【账户已禁用】（临时停用某账号而不删除其文件时，应选“账户已禁用”）。', '{"pdf": "操作技能复习.pdf", "pages": [131, 132, 133]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-3.1 查看系统设备信息。 (node_id=318)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (318, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (318, 1, '[{"id": "s5-3-1-b1", "t": "table", "imp": "core", "title": "Windows 10 查看系统与硬件设备信息的四大工具（必背运行命令）", "headers": ["工具名称", "快捷打开方式 / 运行命令", "主要查看内容与标记含义"], "rows": [["==设备管理器==", "右键【开始】菜单 或 输入 ==`devmgmt.msc`==", "按硬件类别查看所有设备状态：==黄色感叹号 `!` 表示驱动未安装或异常==；红色叉号或向下箭头表示设备已禁用"], ["**系统信息**", "`Win + R` 输入 ==`msinfo32`==", "全面查看操作系统版本、BIOS 模式、主板、处理器及内存详情"], ["**DirectX 诊断工具**", "`Win + R` 输入 ==`dxdiag`==", "查看系统、**显卡（显示）**、声卡（声音）硬件型号与 DirectX 加速状态"], ["**任务管理器**", "==`Ctrl + Shift + Esc`== →【性能】选项卡", "实时查看 CPU、内存、磁盘、以太网/Wi-Fi 与 GPU 利用率及硬件型号"]]}]'::jsonb, '', 'S5-3.1 查看系统设备信息。 Windows 10 查看系统与硬件设备信息的四大工具（必背运行命令） 工具名称 快捷打开方式 / 运行命令 主要查看内容与标记含义 设备管理器 右键【开始】菜单 或 输入 devmgmt.msc 按硬件类别查看所有设备状态：黄色感叹号 ! 表示驱动未安装或异常；红色叉号或向下箭头表示设备已禁用 系统信息 Win + R 输入 msinfo32 全面查看操作系统版本、BIOS 模式、主板、处理器及内存详情 DirectX 诊断工具 Win + R 输入 dxdiag 查看系统、显卡（显示）、声卡（声音）硬件型号与 DirectX 加速状态 任务管理器 Ctrl + Shift + Esc →【性能】选项卡 实时查看 CPU、内存、磁盘、以太网/Wi-Fi 与 GPU 利用率及硬件型号', '{"pdf": "操作技能复习.pdf", "pages": [134, 135]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-3.2 硬件设备驱动安装、更新。 (node_id=319)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (319, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (319, 1, '[{"id": "s5-3-2-b1", "t": "list", "imp": "core", "title": "设备管理器中驱动程序的四大维护操作", "ordered": false, "items": ["更新驱动程序：右键硬件 →【更新驱动程序】，可选“自动搜索驱动”或“浏览我的电脑以查找驱动程序”（指定本地 `.inf` 驱动目录）。", "回退驱动程序（高频考点）：当**更新某硬件驱动后出现蓝屏、闪退或兼容性故障**时，可在硬件【属性】→【驱动程序】选项卡中点击==【回退驱动程序】==恢复到更新前的稳定版本。", "禁用设备 vs 卸载设备：【禁用设备】仅暂停系统对该硬件的调用（物理连接仍在，随时可重新启用）；【卸载设备】则移除该设备节点及驱动绑定。"]}]'::jsonb, '', 'S5-3.2 硬件设备驱动安装、更新。 设备管理器中驱动程序的四大维护操作 更新驱动程序：右键硬件 →【更新驱动程序】，可选“自动搜索驱动”或“浏览我的电脑以查找驱动程序”（指定本地 .inf 驱动目录）。 回退驱动程序（高频考点）：当更新某硬件驱动后出现蓝屏、闪退或兼容性故障时，可在硬件【属性】→【驱动程序】选项卡中点击【回退驱动程序】恢复到更新前的稳定版本。 禁用设备 vs 卸载设备：【禁用设备】仅暂停系统对该硬件的调用（物理连接仍在，随时可重新启用）；【卸载设备】则移除该设备节点及驱动绑定。', '{"pdf": "操作技能复习.pdf", "pages": [136, 137, 138]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-4.1 IP 地址、DNS 服务器的配置。 (node_id=321)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (321, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (321, 1, '[{"id": "s5-4-1-b1", "t": "list", "imp": "core", "title": "IPv4 属性配置四要素与 ipconfig / ping 排错命令", "ordered": false, "items": ["配置入口：打开网络连接面板（`Win + R` 输入 ==`ncpa.cpl`==）→ 右键网卡选【属性】→ 双击 ==【Internet 协议版本 4 (TCP/IPv4)】==。", "手动静态 IP 必填四要素：① **IP 地址**（如 `192.168.1.100`）；② **子网掩码**（C 类默认 `255.255.255.0`）；③ **默认网关**（与本机 IP 必须在同一网段，如 `192.168.1.1`）；④ **首选/备用 DNS 服务器**（用于将域名解析为 IP，如 `114.114.114.114`）。", "必记网络诊断命令：① ==`ipconfig`== 查看基本 IP/掩码/网关；② ==`ipconfig /all`== 查看包含 **MAC 物理地址、DHCP 状态与 DNS 服务器** 在内的完整详情；③ `ipconfig /release` 释放租约、`ipconfig /renew` 重新获取 DHCP 地址、`ipconfig /flushdns` 刷新 DNS 缓存；④ `ping 127.0.0.1` 检测本机 TCP/IP 协议栈是否正常。"]}]'::jsonb, '', 'S5-4.1 IP 地址、DNS 服务器的配置。 IPv4 属性配置四要素与 ipconfig / ping 排错命令 配置入口：打开网络连接面板（Win + R 输入 ncpa.cpl）→ 右键网卡选【属性】→ 双击 【Internet 协议版本 4 (TCP/IPv4)】。 手动静态 IP 必填四要素：① IP 地址（如 192.168.1.100）；② 子网掩码（C 类默认 255.255.255.0）；③ 默认网关（与本机 IP 必须在同一网段，如 192.168.1.1）；④ 首选/备用 DNS 服务器（用于将域名解析为 IP，如 114.114.114.114）。 必记网络诊断命令：① ipconfig 查看基本 IP/掩码/网关；② ipconfig /all 查看包含 MAC 物理地址、DHCP 状态与 DNS 服务器 在内的完整详情；③ ipconfig /release 释放租约、ipconfig /renew 重新获取 DHCP 地址、ipconfig /flushdns 刷新 DNS 缓存；④ ping 127.0.0.1 检测本机 TCP/IP 协议栈是否正常。', '{"pdf": "操作技能复习.pdf", "pages": [139]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-4.2 文件及设备的共享配置。 (node_id=322)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (322, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (322, 1, '[{"id": "s5-4-2-b1", "t": "list", "imp": "core", "title": "局域网文件夹/打印机共享配置与 UNC 访问路径", "ordered": false, "items": ["开启高级共享设置：【控制面板】→【网络和共享中心】→【更改高级共享设置】→ 启用==【网络发现】==和==【文件和打印机共享】==。", "配置文件夹共享：右键目标文件夹 →【属性】→【共享】选项卡 →【高级共享】→ 勾选【共享此文件夹】→ 点击【权限】设置用户权限（**读取 / 更改 / 完全控制**；最终有效权限取“共享权限”与“NTFS 安全权限”的**交集即最严格者**）。", "隐藏共享与 UNC 访问路径：在共享名末尾加上美元符号 ==`$`==（如 `data$`）可创建隐藏共享；局域网其他电脑在文件资源管理器地址栏或【运行】中输入 ==`\\\\目标主机IP或计算机名\\共享名`==（注意是**双反斜杠 `\\\\`**）即可访问。"]}]'::jsonb, '', 'S5-4.2 文件及设备的共享配置。 局域网文件夹/打印机共享配置与 UNC 访问路径 开启高级共享设置：【控制面板】→【网络和共享中心】→【更改高级共享设置】→ 启用【网络发现】和【文件和打印机共享】。 配置文件夹共享：右键目标文件夹 →【属性】→【共享】选项卡 →【高级共享】→ 勾选【共享此文件夹】→ 点击【权限】设置用户权限（读取 / 更改 / 完全控制；最终有效权限取“共享权限”与“NTFS 安全权限”的交集即最严格者）。 隐藏共享与 UNC 访问路径：在共享名末尾加上美元符号 $（如 data$）可创建隐藏共享；局域网其他电脑在文件资源管理器地址栏或【运行】中输入 \\目标主机IP或计算机名\共享名（注意是双反斜杠 \\）即可访问。', '{"pdf": "操作技能复习.pdf", "pages": [140, 141]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-4.3 互联网的连接、应用及选项配置。 (node_id=323)
