INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (323, 1, '[{"id": "s5-4-3-b1", "t": "table", "imp": "core", "title": "Internet 选项（inetcpl.cpl）六大选项卡核心功能对照", "headers": ["选项卡名称", "核心配置项（必考对应关系）"], "rows": [["==常规==", "设置浏览器**主页（Home Page）**、清理浏览历史记录/临时文件/Cookie"], ["==安全==", "将网站划分为四大区域：**Internet、本地 Intranet、受信任的站点、受限制的站点**，分别设置安全级别"], ["**隐私**", "设置 Cookie 拦截策略、位置信息权限及开启/关闭**弹出窗口阻止程序**"], ["**内容**", "管理 SSL 数字证书、配置自动完成表单密码"], ["==连接==", "添加宽带拨号 VPN、点击==【局域网设置】配置代理服务器（Proxy）=="], ["**高级**", "重置浏览器设置、配置 TLS/SSL 加密协议版本"]]}]'::jsonb, '', 'S5-4.3 互联网的连接、应用及选项配置。 Internet 选项（inetcpl.cpl）六大选项卡核心功能对照 选项卡名称 核心配置项（必考对应关系） 常规 设置浏览器主页（Home Page）、清理浏览历史记录/临时文件/Cookie 安全 将网站划分为四大区域：Internet、本地 Intranet、受信任的站点、受限制的站点，分别设置安全级别 隐私 设置 Cookie 拦截策略、位置信息权限及开启/关闭弹出窗口阻止程序 内容 管理 SSL 数字证书、配置自动完成表单密码 连接 添加宽带拨号 VPN、点击【局域网设置】配置代理服务器（Proxy） 高级 重置浏览器设置、配置 TLS/SSL 加密协议版本', '{"pdf": "操作技能复习.pdf", "pages": [142, 143]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-4.4 远程控制的设置与远程桌面连接。 (node_id=324)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (324, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (324, 1, '[{"id": "s5-4-4-b1", "t": "list", "imp": "core", "title": "Windows 远程桌面（RDP）被控端开启与主控端 mstsc 连接", "ordered": false, "items": ["协议与默认端口：Windows 远程桌面基于 **RDP（Remote Desktop Protocol）** 协议，默认监听 TCP 端口号为 ==`3389`==。", "被控端（服务器端）必做设置：右键【此电脑】→【属性】→【远程设置】→【远程】选项卡 → 勾选==【允许远程连接到此计算机】==，且被登录的账户**必须设置非空密码**（空密码账户默认禁止远程桌面登录）。", "主控端（客户端）发起连接：按 `Win + R` 输入命令 ==`mstsc`== 打开【远程桌面连接】，输入目标主机 IP 地址（若改过端口则写 `IP:端口`）及用户名密码即可登录。"]}]'::jsonb, '', 'S5-4.4 远程控制的设置与远程桌面连接。 Windows 远程桌面（RDP）被控端开启与主控端 mstsc 连接 协议与默认端口：Windows 远程桌面基于 RDP（Remote Desktop Protocol） 协议，默认监听 TCP 端口号为 3389。 被控端（服务器端）必做设置：右键【此电脑】→【属性】→【远程设置】→【远程】选项卡 → 勾选【允许远程连接到此计算机】，且被登录的账户必须设置非空密码（空密码账户默认禁止远程桌面登录）。 主控端（客户端）发起连接：按 Win + R 输入命令 mstsc 打开【远程桌面连接】，输入目标主机 IP 地址（若改过端口则写 IP:端口）及用户名密码即可登录。', '{"pdf": "操作技能复习.pdf", "pages": [144, 145]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S5-4.5 Windows 防火墙配置。 (node_id=325)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (325, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (325, 1, '[{"id": "s5-4-5-b1", "t": "list", "imp": "core", "title": "Windows Defender 防火墙三大网络位置与入站/出站规则", "ordered": false, "items": ["三类网络配置文件：==域网络==（企业活动目录域环境）、==专用网络==（受信任的家庭/办公局域网）、==公用网络==（咖啡厅、机场等不受信任公共场所，安全限制最严）。", "高级安全防火墙（运行命令 ==`wf.msc`==）：① **入站规则（Inbound Rules）** 控制外部主机主动访问本机端口/程序的流量（默认阻止未匹配的外部连接；如开启 Web 服务需新建入站规则放行 TCP `80/443` 端口）；② **出站规则（Outbound Rules）** 控制本机软件向外访问互联网的流量（默认放行，可新建规则禁止某软件联网）。"]}]'::jsonb, '', 'S5-4.5 Windows 防火墙配置。 Windows Defender 防火墙三大网络位置与入站/出站规则 三类网络配置文件：域网络（企业活动目录域环境）、专用网络（受信任的家庭/办公局域网）、公用网络（咖啡厅、机场等不受信任公共场所，安全限制最严）。 高级安全防火墙（运行命令 wf.msc）：① 入站规则（Inbound Rules） 控制外部主机主动访问本机端口/程序的流量（默认阻止未匹配的外部连接；如开启 Web 服务需新建入站规则放行 TCP 80/443 端口）；② 出站规则（Outbound Rules） 控制本机软件向外访问互联网的流量（默认放行，可新建规则禁止某软件联网）。', '{"pdf": "操作技能复习.pdf", "pages": [146, 147, 148]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S6-1.1 安装、启动、关闭 Linux 系统。 (node_id=327)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (327, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (327, 1, '[{"id": "s6-1-1-b1", "t": "list", "imp": "core", "title": "CentOS 7 磁盘分区方案、关机与重启命令及 systemd 运行目标", "ordered": false, "items": ["安装必选分区：① ==`/`（根分区）==：Linux 所有目录的唯一起点，必须创建；② ==`swap`（交换分区）==：虚拟内存分区，当物理内存不足时使用；③ `/boot`（引导分区，存放内核与启动引导文件，一般 200MB~1GB）。", "关机命令（必记）：==`shutdown -h now`==（立即关机）、`shutdown -h 10`（10 分钟后关机）、==`poweroff`==、==`halt`==、==`init 0`==。", "重启命令（必记）：==`shutdown -r now`==、==`reboot`==、==`init 6`==（关机或重启前建议先执行 `sync` 将内存缓冲区数据同步写入磁盘）。", "CentOS 7 运行目标（Target）：`systemctl get-default` 查看默认级别；==`multi-user.target`== 对应字符多用户命令行模式（原 `init 3`），==`graphical.target`== 对应图形桌面模式（原 `init 5`）。"]}]'::jsonb, '', 'S6-1.1 安装、启动、关闭 Linux 系统。 CentOS 7 磁盘分区方案、关机与重启命令及 systemd 运行目标 安装必选分区：① /（根分区）：Linux 所有目录的唯一起点，必须创建；② swap（交换分区）：虚拟内存分区，当物理内存不足时使用；③ /boot（引导分区，存放内核与启动引导文件，一般 200MB~1GB）。 关机命令（必记）：shutdown -h now（立即关机）、shutdown -h 10（10 分钟后关机）、poweroff、halt、init 0。 重启命令（必记）：shutdown -r now、reboot、init 6（关机或重启前建议先执行 sync 将内存缓冲区数据同步写入磁盘）。 CentOS 7 运行目标（Target）：systemctl get-default 查看默认级别；multi-user.target 对应字符多用户命令行模式（原 init 3），graphical.target 对应图形桌面模式（原 init 5）。', '{"pdf": "操作技能复习.pdf", "pages": [150, 151]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S6-1.2 本地登录和远程登录。 (node_id=328)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (328, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (328, 1, '[{"id": "s6-1-2-b1", "t": "list", "imp": "core", "title": "命令提示符 `#` vs `$`、虚拟终端切换与 SSH 远程登录", "ordered": false, "items": ["命令提示符身份区分：超级管理员 ==`root` 的提示符末尾为 `#`==（家目录为 ==`/root`==）；==普通用户的提示符末尾为 `$`==（家目录为 ==`/home/用户名`==）。", "SSH 加密远程登录：Linux 默认使用 **SSH（Secure Shell，默认 TCP `22` 端口，守护进程 `sshd`）** 进行远程命令行管理，命令格式为 ==`ssh 用户名@远程主机IP [-p 端口]`==；注销退出当前登录用 `exit` 或 `logout`。"]}]'::jsonb, '', 'S6-1.2 本地登录和远程登录。 命令提示符 # vs $、虚拟终端切换与 SSH 远程登录 命令提示符身份区分：超级管理员 root 的提示符末尾为 #（家目录为 /root）；普通用户的提示符末尾为 $（家目录为 /home/用户名）。 SSH 加密远程登录：Linux 默认使用 SSH（Secure Shell，默认 TCP 22 端口，守护进程 sshd） 进行远程命令行管理，命令格式为 ssh 用户名@远程主机IP [-p 端口]；注销退出当前登录用 exit 或 logout。', '{"pdf": "操作技能复习.pdf", "pages": [152]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S6-2.1 目录与路径。 (node_id=330)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (330, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (330, 1, '[{"id": "s6-2-1-b1", "t": "table", "imp": "core", "title": "Linux 树形标准目录作用与绝对路径 vs 相对路径", "headers": ["目录 / 路径符号", "含义与存放内容（高频必考）"], "rows": [["==`/`（根目录）==", "Linux 单根倒置树结构的顶点；==绝对路径必定以 `/` 开头==（如 `/etc/sysconfig`）"], ["==`.` / `..` / `~` / `-`==", "`.` 当前目录、`..` 上一级父目录、`~` 当前用户家目录、`cd -` 返回上一次所在目录"], ["==`/etc`==", "存放系统和各类服务的**核心配置文件**（如 `/etc/passwd`、`/etc/profile`）"], ["==`/root` vs `/home`==", "`/root` 是超级管理员 root 的家目录；`/home` 存放所有普通用户的家目录"], ["==`/bin` & `/sbin`==", "存放普通用户与系统管理员必备的二进制可执行命令"], ["==`/var` / `/tmp` / `/dev`==", "`/var` 存放常变化的日志（`/var/log`）；`/tmp` 临时文件目录；`/dev` 设备文件目录"]]}]'::jsonb, '', 'S6-2.1 目录与路径。 Linux 树形标准目录作用与绝对路径 vs 相对路径 目录 / 路径符号 含义与存放内容（高频必考） /（根目录） Linux 单根倒置树结构的顶点；绝对路径必定以 / 开头（如 /etc/sysconfig） . / .. / ~ / - . 当前目录、.. 上一级父目录、~ 当前用户家目录、cd - 返回上一次所在目录 /etc 存放系统和各类服务的核心配置文件（如 /etc/passwd、/etc/profile） /root vs /home /root 是超级管理员 root 的家目录；/home 存放所有普通用户的家目录 /bin & /sbin 存放普通用户与系统管理员必备的二进制可执行命令 /var / /tmp / /dev /var 存放常变化的日志（/var/log）；/tmp 临时文件目录；/dev 设备文件目录', '{"pdf": "操作技能复习.pdf", "pages": [153]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S6-2.2 Linux 的基础命令。 (node_id=331)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (331, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (331, 1, '[{"id": "s6-2-2-b1", "t": "list", "imp": "core", "title": "命令语法格式、帮助查询与常用系统基础命令", "ordered": false, "items": ["命令标准格式：`命令名 [选项] [参数]`（严格区分大小写；短选项用单横线如 `-l` 可合并写 `-la`，长选项用双横线如 `--help`）。", "核心基础命令：① ==`man 命令`== 或 `命令 --help` 查帮助手册；② ==`clear`==（或 `Ctrl+L`）清屏；③ ==`history`== 查看历史命令；④ ==`su - 用户名`== 切换用户身份；⑤ `uname -r` 查看内核版本、`whoami` 查看当前有效用户名；⑥ **Tab 键**自动补全命令或文件名，**`Ctrl + C`** 强制中断当前正在运行的命令。"]}]'::jsonb, '', 'S6-2.2 Linux 的基础命令。 命令语法格式、帮助查询与常用系统基础命令 命令标准格式：命令名 [选项] [参数]（严格区分大小写；短选项用单横线如 -l 可合并写 -la，长选项用双横线如 --help）。 核心基础命令：① man 命令 或 命令 --help 查帮助手册；② clear（或 Ctrl+L）清屏；③ history 查看历史命令；④ su - 用户名 切换用户身份；⑤ uname -r 查看内核版本、whoami 查看当前有效用户名；⑥ Tab 键自动补全命令或文件名，Ctrl + C 强制中断当前正在运行的命令。', '{"pdf": "操作技能复习.pdf", "pages": [154]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- S6-2.3 常用文件处理命令。 (node_id=332)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (332, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (332, 1, '[{"id": "s6-2-3-b1", "t": "table", "imp": "core", "title": "Linux 高频文件处理、查找、权限与打包压缩命令大全", "headers": ["命令及核心选项", "功能说明与考试必记要点"], "rows": [["==`touch 文件名`==", "创建空文件，或更新已有文件的时间戳"], ["==`cat` / `more` / `less`==", "`cat -n` 一次性显示全文并带行号；`more` 和 `less` 分页浏览长文件（`q` 退出）"], ["==`head -n K` / `tail -n K`==", "查看文件**前 K 行** / **后 K 行**（默认 10 行）；==`tail -f 日志文件`== 实时动态追踪日志追加"], ["==`cp [-r] 源 目标`==", "复制文件；**复制目录时必须加 `-r`（递归）选项**"], ["==`mv 源 目标`==", "移动文件/目录，或在同目录下对文件**重命名**"], ["==`rm [-rf] 文件/目录`==", "删除文件；**`-r` 递归删目录，`-f` 强制删除不提示**"], ["==`grep [-in] ''词'' 文件`==", "在文件内容中按行搜索匹配字符串（`-i` 忽略大小写，`-n` 显示行号）"], ["==`chmod 755 文件`==", "修改权限：`r=4, w=2, x=1`；`755` 即 `rwxr-xr-x`（属主读写执行，属组和其他人读执行）"], ["==`tar -zcvf` vs `tar -zxvf`==", "打包压缩 `.tar.gz` 用 **`-zcvf`**（`c` 创建）；解压 `.tar.gz` 用 **`-zxvf`**（`x` 解包，`-C` 指定解压目录）"]]}, {"id": "s6-2-3-b2", "t": "list", "imp": "core", "title": "vi / vim 编辑器三种工作模式切换（必考）", "ordered": false, "items": ["三种模式：① **命令模式（一般模式）**：刚打开 `vi filename` 时的默认模式，可按 `yy` 复制行、`p` 粘贴、`dd` 删除当前行；② **输入/编辑模式**：在命令模式下按 ==`i`、`a` 或 `o`== 进入，可自由输入文本，按 ==`Esc` 键==退回命令模式；③ **末行模式（底行模式）**：在命令模式下输入冒号 ==`:`== 进入，输入 ==`:wq` 保存并退出==、==`:q!` 不保存强制退出==、`:set nu` 显示行号。"]}]'::jsonb, '', 'S6-2.3 常用文件处理命令。 Linux 高频文件处理、查找、权限与打包压缩命令大全 命令及核心选项 功能说明与考试必记要点 touch 文件名 创建空文件，或更新已有文件的时间戳 cat / more / less cat -n 一次性显示全文并带行号；more 和 less 分页浏览长文件（q 退出） head -n K / tail -n K 查看文件前 K 行 / 后 K 行（默认 10 行）；tail -f 日志文件 实时动态追踪日志追加 cp [-r] 源 目标 复制文件；复制目录时必须加 -r（递归）选项 mv 源 目标 移动文件/目录，或在同目录下对文件重命名 rm [-rf] 文件/目录 删除文件；-r 递归删目录，-f 强制删除不提示 grep [-in] ''词'' 文件 在文件内容中按行搜索匹配字符串（-i 忽略大小写，-n 显示行号） chmod 755 文件 修改权限：r=4, w=2, x=1；755 即 rwxr-xr-x（属主读写执行，属组和其他人读执行） tar -zcvf vs tar -zxvf 打包压缩 .tar.gz 用 -zcvf（c 创建）；解压 .tar.gz 用 -zxvf（x 解包，-C 指定解压目录） vi / vim 编辑器三种工作模式切换（必考） 三种模式：① 命令模式（一般模式）：刚打开 vi filename 时的默认模式，可按 yy 复制行、p 粘贴、dd 删除当前行；② 输入/编辑模式：在命令模式下按 i、a 或 o 进入，可自由输入文本，按 Esc 键退回命令模式；③ 末行模式（底行模式）：在命令模式下输入冒号 : 进入，输入 :wq 保存并退出、:q! 不保存强制退出、:set nu 显示行号。', '{"pdf": "操作技能复习.pdf", "pages": [155, 156, 157, 158]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

