INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (333, 1, '[{"id": "s6-2-4-b1", "t": "table", "imp": "core", "title": "Linux 五大目录操作命令（pwd / cd / ls / mkdir / rmdir）", "headers": ["命令及高频选项", "功能说明与真题考点"], "rows": [["==`pwd`==", "显示当前工作目录的**完整绝对路径**（Print Working Directory）"], ["==`cd [目录路径]`==", "切换工作目录：`cd ~` 或直接 `cd` 回到家目录，`cd ..` 回上级目录，`cd /` 到根目录"], ["==`ls [-la]`==", "列出目录内容：==`-a` 显示包含以 `.` 开头的隐藏文件==，==`-l` 以长格式显示权限/属主/大小==（简写 `ll`）"], ["==`mkdir [-p] 目录路径`==", "创建新目录；==创建多级嵌套目录（如 `mkdir -p a/b/c`）必须加 `-p` 选项=="], ["`rmdir` vs `rm -rf`", "`rmdir` **只能删除空目录**；删除非空目录必须用 ==`rm -rf 目录名`=="]]}]'::jsonb, '', 'S6-2.4 常用目录处理命令。 Linux 五大目录操作命令（pwd / cd / ls / mkdir / rmdir） 命令及高频选项 功能说明与真题考点 pwd 显示当前工作目录的完整绝对路径（Print Working Directory） cd [目录路径] 切换工作目录：cd ~ 或直接 cd 回到家目录，cd .. 回上级目录，cd / 到根目录 ls [-la] 列出目录内容：-a 显示包含以 . 开头的隐藏文件，-l 以长格式显示权限/属主/大小（简写 ll） mkdir [-p] 目录路径 创建新目录；创建多级嵌套目录（如 mkdir -p a/b/c）必须加 -p 选项 rmdir vs rm -rf rmdir 只能删除空目录；删除非空目录必须用 rm -rf 目录名', '{"pdf": "操作技能复习.pdf", "pages": [159, 160, 161, 162]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

