INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (335, 1, '[{"id": "s6-3-1-b1", "t": "table", "imp": "core", "title": "CentOS 7 三大核心网络配置文件路径与关键字段（必背）", "headers": ["配置类别", "文件绝对路径", "核心配置参数与维护命令"], "rows": [["==网卡配置文件==", "==`/etc/sysconfig/network-scripts/ifcfg-ens33`==（或 `ifcfg-eth0`）", "==`BOOTPROTO=static`（静态）或 `dhcp`（动态）==、==`ONBOOT=yes`（开机自启网卡）==、`IPADDR`、`NETMASK`（或 `PREFIX=24`）、`GATEWAY`、`DNS1`"], ["==DNS 客户端配置==", "==`/etc/resolv.conf`==", "格式为 `nameserver 114.114.114.114`（指定 DNS 解析服务器 IP）"], ["==主机名配置文件==", "==`/etc/hostname`==（本地 IP-主机名映射文件为 `/etc/hosts`）", "查看主机名用 `hostname`；永久修改主机名命令：==`hostnamectl set-hostname 新主机名`=="]]}]'::jsonb, '', 'S6-3.1 网卡配置文件、DNS 配置文件、主机名配置文件。 CentOS 7 三大核心网络配置文件路径与关键字段（必背） 配置类别 文件绝对路径 核心配置参数与维护命令 网卡配置文件 /etc/sysconfig/network-scripts/ifcfg-ens33（或 ifcfg-eth0） BOOTPROTO=static（静态）或 dhcp（动态）、ONBOOT=yes（开机自启网卡）、IPADDR、NETMASK（或 PREFIX=24）、GATEWAY、DNS1 DNS 客户端配置 /etc/resolv.conf 格式为 nameserver 114.114.114.114（指定 DNS 解析服务器 IP） 主机名配置文件 /etc/hostname（本地 IP-主机名映射文件为 /etc/hosts） 查看主机名用 hostname；永久修改主机名命令：hostnamectl set-hostname 新主机名', '{"pdf": "操作技能复习.pdf", "pages": [163, 164, 165]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

