INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (336, 1, '[{"id": "s6-3-2-b1", "t": "list", "imp": "core", "title": "NetworkManager 服务控制与 nmcli / nmtui / ip 命令", "ordered": false, "items": ["管理网络服务（systemctl）：==`systemctl restart network`== 或 `systemctl restart NetworkManager` 重启网络使配置生效；`systemctl status NetworkManager` 查看状态；`systemctl enable NetworkManager` 设为开机自启。", "NetworkManager 工具集：① ==`nmcli`==（命令行管理工具，如 `nmcli device status` 查看网卡状态，`nmcli connection reload` 重载配置）；② ==`nmtui`==（伪图形文本菜单交互配置工具）；③ ==`ip addr`==（或 `ifconfig`）查看网卡 IP 与 MAC 地址。"]}]'::jsonb, '', 'S6-3.2 网络配置工具 NetworkManager。 NetworkManager 服务控制与 nmcli / nmtui / ip 命令 管理网络服务（systemctl）：systemctl restart network 或 systemctl restart NetworkManager 重启网络使配置生效；systemctl status NetworkManager 查看状态；systemctl enable NetworkManager 设为开机自启。 NetworkManager 工具集：① nmcli（命令行管理工具，如 nmcli device status 查看网卡状态，nmcli connection reload 重载配置）；② nmtui（伪图形文本菜单交互配置工具）；③ ip addr（或 ifconfig）查看网卡 IP 与 MAC 地址。', '{"pdf": "操作技能复习.pdf", "pages": [166, 167, 168, 169, 170]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

