INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (338, 1, '[{"id": "s6-4.1-b1", "t": "list", "imp": "core", "title": "YUM 软件仓库目录、.repo 配置文件字段与缓存命令", "ordered": false, "items": ["YUM 源配置目录与文件扩展名：所有 YUM 仓库配置文件均存放在 ==`/etc/yum.repos.d/`== 目录下，且文件名==必须以 `.repo` 结尾==（如 `CentOS-Base.repo`）。", "`.repo` 文件五大核心字段：① `[仓库ID]`（方括号内唯一标识）；② `name=...`（仓库描述）；③ ==`baseurl=...`==（仓库地址，支持 `http://`、`https://`、`ftp://` 及本地光盘镜像 ==`file:///mnt/cdrom`==）；④ ==`enabled=1`==（`1` 启用该源，`0` 禁用）；⑤ ==`gpgcheck=0`==（`1` 开启 GPG 签名校验，`0` 不校验）。", "更新仓库缓存：修改 `.repo` 后执行 ==`yum clean all`== 清空旧缓存，再执行 ==`yum makecache`== 生成新缓存（`yum repolist` 查看可用源列表）。"]}]'::jsonb, '', 'S6-4.1 设置软件仓库。 YUM 软件仓库目录、.repo 配置文件字段与缓存命令 YUM 源配置目录与文件扩展名：所有 YUM 仓库配置文件均存放在 /etc/yum.repos.d/ 目录下，且文件名必须以 .repo 结尾（如 CentOS-Base.repo）。 .repo 文件五大核心字段：① [仓库ID]（方括号内唯一标识）；② name=...（仓库描述）；③ baseurl=...（仓库地址，支持 http://、https://、ftp:// 及本地光盘镜像 file:///mnt/cdrom）；④ enabled=1（1 启用该源，0 禁用）；⑤ gpgcheck=0（1 开启 GPG 签名校验，0 不校验）。 更新仓库缓存：修改 .repo 后执行 yum clean all 清空旧缓存，再执行 yum makecache 生成新缓存（yum repolist 查看可用源列表）。', '{"pdf": "操作技能复习.pdf", "pages": [171, 172, 173]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

