INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (339, 1, '[{"id": "s6-4-2-b1", "t": "table", "imp": "core", "title": "yum 与 rpm 软件包管理常用命令对比（必背）", "headers": ["操作目的", "yum 命令（自动解决依赖关系）", "rpm 命令（底层管理，不自动解依赖）"], "rows": [["**安装软件包**", "==`yum [-y] install 软件名`==（`-y` 自动确认全选 yes）", "==`rpm -ivh 包全名.rpm`==（`i` 安装，`v` 详情，`h` 进度条）"], ["**升级软件包**", "==`yum [-y] update [软件名]`==", "`rpm -Uvh 包全名.rpm`"], ["**卸载软件包**", "==`yum [-y] remove 软件名`==（或 `erase`）", "==`rpm -e 软件名`=="], ["**查询与搜索**", "`yum list`、`yum search 关键词`、`yum info 软件名`", "==`rpm -qa` 查所有已装包==，`rpm -qi` 查信息，`rpm -ql` 查安装文件列表"]]}]'::jsonb, '', 'S6-4.2 使用 yum 安装软件。 yum 与 rpm 软件包管理常用命令对比（必背） 操作目的 yum 命令（自动解决依赖关系） rpm 命令（底层管理，不自动解依赖） 安装软件包 yum [-y] install 软件名（-y 自动确认全选 yes） rpm -ivh 包全名.rpm（i 安装，v 详情，h 进度条） 升级软件包 yum [-y] update [软件名] rpm -Uvh 包全名.rpm 卸载软件包 yum [-y] remove 软件名（或 erase） rpm -e 软件名 查询与搜索 yum list、yum search 关键词、yum info 软件名 rpm -qa 查所有已装包，rpm -qi 查信息，rpm -ql 查安装文件列表', '{"pdf": "操作技能复习.pdf", "pages": [174, 175]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- 1. 先按关联题投票将 S2~S6 二级直挂知识点下沉到对应三级节点
WITH q_vote AS (
  SELECT k.id AS kp_id,
         q.chapter_id AS target_l3,
         ROW_NUMBER() OVER (PARTITION BY k.id ORDER BY count(*) DESC, q.chapter_id) AS rn
    FROM t_knowledge_point k
    JOIN t_question_kp x ON x.kp_id = k.id
    JOIN t_question q ON q.id = x.question_id AND NOT q.deleted
    JOIN t_chapter ch ON ch.id = q.chapter_id AND ch.parent_id = k.node_id AND ch.level = 3
   WHERE NOT k.deleted
     AND k.node_id IN (270, 272, 277, 283, 287, 291, 295, 299, 303, 307, 311, 314, 317, 320, 326, 329, 334, 337)
   GROUP BY k.id, q.chapter_id
)
UPDATE t_knowledge_point k
   SET node_id = v.target_l3
  FROM q_vote v
 WHERE k.id = v.kp_id AND v.rn = 1;

-- 2. 对剩余无关联题投票的 S2~S6 二级直挂知识点按标题/内容特征归入对应三级节点
UPDATE t_knowledge_point k
   SET node_id = CASE
     WHEN k.node_id = 270 THEN 271
     WHEN k.node_id = 272 THEN
       CASE
         WHEN k.title ~* 'CREATE\s+DATABASE|ALTER\s+DATABASE|USE\s+|字符集|数据库' AND k.title !~* '表|DROP' THEN 273
         WHEN k.title ~* 'DROP|删除表|删除数据库|TRUNCATE' THEN 276
         WHEN k.title ~* 'ALTER\s+TABLE|MODIFY|CHANGE|RENAME|修改表' THEN 275
         ELSE 274
       END
     WHEN k.node_id = 277 THEN
       CASE
         WHEN k.title ~* 'INSERT|UPDATE|DELETE|插入|修改|删除数据' THEN 278
         WHEN k.title ~* '子查询|IN|EXISTS|ANY|ALL|嵌套' THEN 280
         WHEN k.title ~* 'GROUP\s+BY|HAVING|ORDER\s+BY|LIMIT|排序|分组' THEN 281
         WHEN k.title ~* 'COUNT|SUM|AVG|MAX|MIN|函数|聚合|汇总' THEN 282
         ELSE 279
       END
     WHEN k.node_id = 283 THEN
       CASE
         WHEN k.title ~* '索引|INDEX' THEN 286
         WHEN k.title ~* '检索|更新视图|修改.*视图|查询视图' THEN 285
         ELSE 284
       END
     WHEN k.node_id = 287 THEN
       CASE
         WHEN k.title ~* '描述|规约|前置|后置|事件流' THEN 289
         WHEN k.title ~* '绘制|include|extend|包含|扩展|关系' THEN 290
         ELSE 288
       END
     WHEN k.node_id = 291 THEN
       CASE
         WHEN k.title ~* '对象图|链' THEN 294
         WHEN k.title ~* '关联|聚合|组合|泛化|依赖|实现|多重性|绘制' THEN 293
         ELSE 292
       END
     WHEN k.node_id = 295 THEN
       CASE
         WHEN k.title ~* '同步|异步|返回|消息类型' THEN 297
         WHEN k.title ~* '绘制|片段|loop|alt|opt' THEN 298
         ELSE 296
       END
     WHEN k.node_id = 299 THEN
       CASE
         WHEN k.title ~* '初态|终态|标记|符号|转移' THEN 301
         WHEN k.title ~* '绘制|entry|exit|do' THEN 302
         ELSE 300
       END
     WHEN k.node_id = 303 THEN
       CASE
         WHEN k.title ~* '拓扑|星型|总线|环型|树型|网状' THEN 304
         WHEN k.title ~* '交换机|路由器|集线器|网卡|设备' THEN 305
         ELSE 306
       END
     WHEN k.node_id = 307 THEN
       CASE
         WHEN k.title ~* 'Ad-Hoc|Infrastructure|组网模式|802\.11' THEN 308
         WHEN k.title ~* 'SSID|WPA|WEP|安全|加密' THEN 309
         ELSE 310
       END
     WHEN k.node_id = 311 THEN
       CASE
         WHEN k.title ~* 'Windows\s*功能|启用或关闭|IIS|Telnet' THEN 312
         ELSE 313
       END
     WHEN k.node_id = 314 THEN
       CASE
         WHEN k.title ~* '创建|删除|添加.*账户|net\s+user' THEN 315
         ELSE 316
       END
     WHEN k.node_id = 317 THEN
       CASE
         WHEN k.title ~* '驱动|更新|回退|禁用' THEN 319
         ELSE 318
       END
     WHEN k.node_id = 320 THEN
       CASE
         WHEN k.title ~* '共享|UNC|打印机' THEN 322
         WHEN k.title ~* 'Internet\s*选项|主页|代理|Cookie' THEN 323
         WHEN k.title ~* '远程桌面|mstsc|3389' THEN 324
         WHEN k.title ~* '防火墙|入站|出站' THEN 325
         ELSE 321
       END
     WHEN k.node_id = 326 THEN
       CASE
         WHEN k.title ~* '登录|ssh|root|提示符' THEN 328
         ELSE 327
       END
     WHEN k.node_id = 329 THEN
       CASE
         WHEN k.title ~* '路径|/etc|/home|/var|根目录' THEN 330
         WHEN k.title ~* 'pwd|cd|ls|mkdir|rmdir|目录' THEN 333
         WHEN k.title ~* 'touch|cat|more|less|head|tail|cp|mv|rm|grep|chmod|tar|vi|vim|文件' THEN 332
         ELSE 331
       END
     WHEN k.node_id = 334 THEN
       CASE
         WHEN k.title ~* 'NetworkManager|nmcli|nmtui|systemctl' THEN 336
         ELSE 335
       END
     WHEN k.node_id = 337 THEN
       CASE
         WHEN k.title ~* 'repo|仓库|yum\.repos\.d|baseurl|gpgcheck' THEN 338
         ELSE 339
       END
   END
 WHERE NOT k.deleted
   AND k.node_id IN (270, 272, 277, 283, 287, 291, 295, 299, 303, 307, 311, 314, 317, 320, 326, 329, 334, 337);

COMMIT;
